quests[42522] = { id = 42522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der neue Kopf der Illidari", description = "Illidan hat Euch offiziell das Kommando übertragen, {name}. Die Illidari gehören jetzt Euch.\n\nWir treffen uns oben und verkünden es allen gemeinsam.", sourceObjective = "Geht nach oben und nehmt Euren Platz als <neuer Anführer/neue Anführerin> der Illidari ein.", completion = "Bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[42523] = { id = 42523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Da wir nun Champions für unseren Orden gewonnen haben, können wir die Späherkarte nutzen, um wichtige Aufträge auf den Verheerten Inseln abzuschließen.\n\nIm Laufe der Jahre haben unsere Späher immer Ausschau nach Jägern gehalten, die wir eines Tages aufnehmen könnten. Eine davon ist Lenara, die auf ihrem Weg zur Volltrefferhütte angegriffen wurde.\n\nIch schlage vor, dass wir Loren Sturmhuf entsenden, um sie zu retten. Er ist für diese Aufgabe wahrscheinlich perfekt geeignet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Lenara braucht Hilfe\" ab.", progress = "Wie verläuft die Mission?", completion = "Gut, Eure Champions hatten Erfolg auf ihrer Mission! Bald sehen wir hier womöglich einige neue Gesichter.", sourceObjectiveStatus = "unverified-source-field" }
quests[42524] = { id = 42524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Unsere Champions haben die talentierte Rekrutiererin Lenara angeworben, die eine außergewöhnlich gute Bogenschützin ist.\n\nSie schafft es, selbst kleinste Ziele auf größte Entfernungen zu treffen. Ihre Pfeile treffen immer das Ziel.\n\nSprecht mit ihr und bildet einen Trupp Bogenschützen aus.", sourceObjective = "Sprecht mit Rekrutiererin Lenara und bildet einen Trupp Bogenschützen aus.", progress = "Wie ist die Ausbildung verlaufen?", completion = "Ausgezeichnet. Diese Trupps werden bei der Verteidigung der Verheerten Inseln unschätzbare Dienste leisten. Ihr könnt sie genauso auf Missionen schicken wie die Champions.", sourceObjectiveStatus = "unverified-source-field" }
quests[42525] = { id = 42525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Es wird Zeit, unsere frisch ausgebildeten Bogenschützen ins Feld zu schicken. Seht Euch die Späherkarte an und schickt Eure Champions und Trupps auf eine Routineerkundungsmission.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Truppen im Feld\" ab.", progress = "Wie ist es gelaufen?", completion = "Die Aufklärungsmission war noch erfolgreicher, als wir erwartet hatten, {name}. Eure Truppen konnten Überlebenskünstler Bahn, einen listigen Strategen, retten.\n\nZum Dank hat er angeboten, uns zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42526] = { id = 42526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Welch glückliche Fügung, dass wir auf Überlebenskünstler Bahn gestoßen sind. Als er noch jung war, hat er in Pandaria gelebt und sein Überleben ausschließlich durch die heimische Flora und Fauna sichergestellt.\n\nSeine Erfahrungen, mit begrenzten Mitteln etwas zu erschaffen, sollten äußerst nützlich dabei sein, die Volltrefferhütte in etwas Großartiges zu verwandeln.\n\nSprecht mit ihm und seht, was er für uns tun kann.", sourceObjective = "Sprecht mit Überlebenskünstler Bahn in der Volltrefferhütte.", completion = "Ausgezeichnete Wahl, {name}. Überlebenskünstler Bahn hat die Hütte zu seiner Heimat erkoren, also sprecht einfach mit ihm, wenn Ihr Verbesserungen vornehmen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42527] = { id = 42527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Portal - Guard Station" }
