quests[42531] = { id = 42531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Portal - Abandoned Shack" }
quests[42532] = { id = 42532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Portal - Rear Entrance" }
quests[42533] = { id = 42533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verfallene Königreich", description = "Der Lichkönig hat also den zweiten der Vier Reiter offenbart... Offensichtlich können selbst Könige nicht mehr ruhen, wenn die Welt um sie herum brennt.\n\nDann soll es so sein, <Todesgebieter/Todesgebieterin>.\n\nIch werde Nazgrim und Thassarian mitteilen, dass sie Euch bei der gefallenen Burg Stromgarde treffen sollen.\n\nPrinz Galen Trollbann hat den Schlüssel zum Grabmal seines Vaters, ein berühmtes Schwert namens Trol'kalar. Um den König als zweiten der Vier Reiter auferstehen zu lassen, müssen wir uns Zutritt zum Grabmal verschaffen.\n\nTut, was notwendig ist, um Galen davon zu überzeugen, uns zu helfen...", sourceObjective = "Sprecht mit Prinz Galen Trollbann in Stromgarde.", completion = "Zu welchem Zweck dringt Ihr in mein Königreich ein, {class}? Sprecht rasch, ich habe nur wenig Geduld...", sourceObjectiveStatus = "unverified-source-field" }
quests[42534] = { id = 42534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere ältesten Feinde", description = "Ich werde der Schwarzen Klinge Zugang zum Grab meines Vaters gewähren. Zunächst bitte ich aber um einen Gefallen.\n\nIch habe Schwert und Banner meines Vaters übernommen. Ich habe Stromgarde zurückerobert, und seine früheren Bewohner sind meine Wachen. Doch es bleibt noch eine Aufgabe.\n\nEindringlinge der Bleichborken haben sich im früheren Magierviertel der Stadt verschanzt. Meine Leute haben herbe Verluste durch sie erlitten.\n\nLöscht sie aus bis auf den letzten Mann! Bringt mir ihre Köpfe und ich werde Euch geben, wonach Ihr trachtet.\n\nIch gebe Euch mein Wort als König von Stromgarde.", sourceObjective = "Sammelt 15 Köpfe von Trollen der Bleichborken.", progress = "Habt Ihr die Köpfe meiner Feinde? Ich will jedem Einzelnen ins Gesicht sehen...", completion = "Bald werden die Köpfe meiner Feinde die Mauern meines Königreichs säumen! Die hier sind nur der Anfang.\n\nNicht einmal Sylvanas wird es wagen, ihren Fuß in das freie Königreich von Stromgarde zu setzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42535] = { id = 42535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod... und Verfall", description = "Meine Familie kämpft seit Generationen gegen die Trolle der Bleichborken... Ihre Anwesenheit in Arathi war schon immer ein Fluch für das Land. Ich will sie endgültig aus Stromgarde vertreiben!\n\nVernichtet ihre Vorräte, dann haben sie keinen Grund, zurückzukehren. Verseucht ihre Vorräte... oder was immer Ihr Todesritter tut, um Dinge zu schänden. Es ist mir gleich.\n\nStellt nur sicher, dass es getan wird!", sourceObjective = "Verseucht 10 Vorräte der Bleichborken.", completion = "Ihr habt meinem Königreich einen Dienst erwiesen, {class}. Stromgarde wird nicht vergessen, was Ihr heute für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42536] = { id = 42536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königsmord", description = "Galen Trollbann ist ein Dummkopf, wenn er glaubt, dass er die Schwarze Klinge betrügen kann.\n\nIch habe genug von seinen Spielchen. Der gefallene Prinz verschwendet unsere Zeit, indem er auf einem verfallenen Thron den König spielt, während Helden ihr Leben geben, um diese Welt zu retten.\n\nWenn Galen Trollbann nicht die Grabstätte seines Vater öffnen will, dann müssen wir das Schwert nehmen und es selbst tun.\n\nSollte er sich widersetzen, dann ist das eben so.", sourceObjective = "Beschafft Trol'kalar von Prinz Galen Trollbann.", progress = "Wir brauchen das Schwert Trol'kalar, um sein Grab zu öffnen. Habt Ihr es gefunden?", completion = "Wir haben jetzt lange genug gezögert, Todesgebieter. Es ist Zeit, das Grab zu öffnen und unseren Champion auferstehen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42537] = { id = 42537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König erhebt sich", description = "König Thoras war einer der größten Krieger, den es je auf dieser Welt gegeben hat.\n\nSein Volk liebte ihn und seine Feinde fürchteten ihn. Er sprach immer nur die Wahrheit und sprach oft das aus, was andere nicht zu sagen wagten.\n\nKönig Thoras lebte ein Kriegerleben und er verdient sicher seinen Frieden im Tod. Doch er ist kein Mann, der friedlich schlafen würde, während die Welt um ihn herum in Flammen steht.\n\nDie Zeit ist gekommen, <Todesgebieter/Todesgebieterin>, den letzten wahren König von Stromgarde in den Armen der Toten und Verdammten zu begrüßen.", sourceObjective = "Lasst König Thoras Trollbann als Todesritter wiederauferstehen.", completion = "Heute ist ein großer König von den Toten auferstanden, um erneut das Schwert im Namen der Freiheit zu führen.\n\nEs wird eine Ehre sein, an seiner Seite gegen die Legionen des Schreckens zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42538] = { id = 42538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42539] = { id = 42539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantel und Degen", description = "<Die Kultisten scheinen eine Operationsbasis in Dunkelhain zu unterhalten. Zumindest Althea Schwarzhaupt zählt zu ihren Mitgliedern, aber möglicherweise ist die gesamte Nachtwache unterwandert worden.>\n\n<Die beste Vorgehensweise wäre jetzt, ihnen die Hilfsmittel für ihr dunkles Ritual abzunehmen und zu versuchen, Althea den Garaus zu machen. Garona muss vorerst warten.>", sourceObjective = "Beschafft den Schädel des Unschuldigen sowie das Blut des Unschuldigen und versucht, Althea Schwarzhaupt in Dunkelhain den Garaus zu machen.", sourceObjectiveStatus = "unverified-source-field" }
