quests[42567] = { id = 42567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Verdorren verdammt", description = "Cedonu hat also gesagt, er hätte Nachtsüchtige in die Leygrotte gehen sehen?\n\nDas gefällt mir überhaupt nicht.\n\nGroßvater scheint gut allein zurechtzukommen, aber der Erzmagier und ich werden ein Auge auf ihn haben. Ihr solltet Eurerseits mal diese Höhlen untersuchen.", sourceObjective = "Sucht die Nachtsüchtigen, die in die Leygrotte gegangen sind.", completion = "{name}? Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[42568] = { id = 42568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung", description = "<Nach Altheas Entkommen ist nur noch ein Ort denkbar: Sturmwind.>\n\n<Wenn Garona dem Kult auch so dicht auf den Fersen ist, trifft sie jetzt ganz sicher Vorbereitungen, um die Stadt zu infiltrieren.>\n\n<Ihr müsst sie unbedingt finden, bevor Ihr Euch in die Stadt begebt.>", sourceObjective = "Findet Garona die Halborcin außerhalb von Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Wenn Ihr mir beistehen wollt, dann tränkt Eure Klingen jetzt in Gift. Das wird eine blutige Angelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[42569] = { id = 42569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Shrine - Azsuna Earth 01" }
