quests[42581] = { id = 42581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Shrine - Valsharah Wind 01" }
quests[42583] = { id = 42583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Der Niedergang der Legion kann nicht allein herbeigeführt werden.\n\nUm diesen Krieg zu gewinnen, müssen wir wie in früheren Zeiten zusammenarbeiten.\n\nUnd dazu müssen wir erst einmal weitere Druiden rekrutieren, die uns helfen können. Sprecht mit der Trollfrau Zen'tabra und dem Nachtelfen Naralex.\n\nSie sind beide fähige Druiden und werden sicherlich bei der Verteidigung des Hains der Träume helfen wollen.", sourceObjective = "Rekrutiert Zen'tabra und Naralex.", completion = "Gut. Ich kenne Zen'tabra und Naralex. Sie werden dem Hain der Träume tapfer dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42584] = { id = 42584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwester Lilith", description = "Wir brauchen noch weitere Verbündete an unserer Seite, wenn wir wirklich etwas erreichen wollen, <Erzdruide/Erzdruidin>. Eine fähige Dryade namens Schwester Lilith ist gerade auf dem Weg zum Hain der Träume, aber wir haben gehört, dass sie möglicherweise in Gefahr ist.\n\nSchickt Zen'tabra los, um ihr zu helfen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Schwester Lilith\" ab.", progress = "Beeilt Euch. Schwester Lilith steckt in Schwierigkeiten.", completion = "Hervorragend, {name}. Zen'tabra hat sich tapfer geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42585] = { id = 42585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Unsere Champions haben auf ihren Reisen mit Schwester Lilith Kontakt aufgenommen. Sie ist die furchtlose Anführerin der Lachenden Schwestern.\n\nSie wird von den Dryaden gleichermaßen als erfahrene Kriegerin wie auch als anspruchsvolle Lehrmeisterin verehrt. Als Rekrutiererin wird sie ausgezeichnete Arbeit verrichten.\n\nSprecht am besten sofort mit ihr und rekrutiert einige Treants.", sourceObjective = "Sprecht mit Schwester Lilith und rekrutiert einige Treants.", progress = "Zusätzliche Truppen werden uns bei den kommenden Missionen gute Dienste leisten.", completion = "Gut gemacht. Ich wusste, Schwester Lilith würde uns nicht enttäuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42586] = { id = 42586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Hains", description = "Wir haben eine neue Mission, um die wir uns kümmern müssen, <Erzdruide/Erzdruidin>. Tief in den Wäldern von Val'sharah wird ein kleiner druidischer Außenposten namens der Hain von Shal'doren von Satyrn angegriffen.\n\nIhr müsst sofort unsere Champions dorthin entsenden, {name}, damit sie sich um diese Bedrohung kümmern. Wir können diese Angriffe der Satyrn auf keinen Fall hinnehmen!", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Die Verteidigung des Hains\" ab.", completion = "Die Mission war nicht nur ein Erfolg, sondern unsere Champions konnten sogar ein beschriebenes Blatt mit uraltem Wissen bergen. Das wird Blattbart den Erzähler, das im Norden lebende Urtum der Lehren, sicher sehr interessieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42588] = { id = 42588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buschfunk", description = "Blattbart wird nicht umsonst \"der Erzähler\" genannt.\n\nEs heißt, er kennt sogar noch Geschichten aus der Zeit vor der Zerschlagung. Wenn er das von unseren Champions geborgene beschriebene Blatt studiert hat, kann er daraus vielleicht neues Wissen und Verbesserungsvorschläge für den Hain ableiten.\n\nBringt es ihm jetzt.", sourceObjective = "Sprecht mit Blattbart dem Erzähler im Hain der Träume in Val'sharah.", completion = "Gut gemacht! Wie ich sehe, hat sich Blattbarts Rat bereits als nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42590] = { id = 42590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familienzusammenführung mit Moozy", description = "Ihr habt ja keine Vorstellung, wie dankbar wir Euch sind, {race}. Dank Euch sind Moozy und mein Mann in Sicherheit. Ich werde die beiden jetzt nicht mehr aus den Augen lassen!\n\nUnd es tut mir leid, aber ich muss Euch um einen letzten Gefallen bitten: Könntet Ihr bitte meine Mutter aufsuchen und sie hierherbringen, damit sie sieht, dass ihr Enkelkind in Sicherheit ist?\n\nIhr Name ist Ethel und sie lebt am nördlichen Rand von Donnertotem.", sourceObjective = "Sucht Ethel Wasserweise auf und bringt sie zu ihrer Familie in der Wiege des Hammers in Donnertotem.", progress = "Ich möchte Euch vielmals danken.", completion = "Eure Güte werden wir nie vergessen. Ihr seid jetzt ein Freund der Familie, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42591] = { id = 42591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette - Hannval the Butcher" }
quests[42593] = { id = 42593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Herangehensweise", description = "In den schwarzen Tempel zu gelangen, könnte knifflig werden. Nachdem der Rat der Schwarzen Ernte eingedrungen war, hat Akama seine Sha'tarpriester angewiesen, eine heilige Barriere zu errichten. Ich kann jedoch nicht durch sie hindurchteleportieren.\n\nWomöglich kenne ich aber einen Weg, diesen Schutz zu umgehen und uns direkt zur Tempelspitze zu bringen.\n\nVor langer Zeit war ich mit einem Zauberer der Hochelfen namens Lan'dalock... liiert. Später hat er sich den Kirin Tor angeschlossen.\n\nWenn Ihr ihn ganz lieb bittet und dabei meinen Namen fallen lasst, würde er uns sicherlich helfen.", sourceObjective = "Sucht nach Erzmagier Lan'dalock in der Violetten Zitadelle in Dalaran.", completion = "Die Matronenmutter?\n\n<Das Gesicht des Erzmagiers wird rot, er hustet, als ob er sich verschluckt hätte, und sieht sich verstohlen um.>\n\nJa, natürlich. Alles für Malicia.", sourceObjectiveStatus = "unverified-source-field" }
quests[42594] = { id = 42594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartige Bewegung", description = "Entschuldigt die holografische Projektion... Ich muss heutzutage buchstäblich an zwei Orten gleichzeitig sein.\n\nEine heilige Barriere, die Schutz vor Teufelsmagie bietet, sagt Ihr? Ich habe genau das Richtige, um das zu umgehen und Malicias Teleportation zu ermöglichen.\n\n<Während der Hochelf in seinem Rucksack kramt, macht sich ein bestürzter Ausdruck auf seinem Gesicht breit.>\n\nWie listig! Seht... Dieser Wichtel hat sich gerade damit davongemacht!", sourceObjective = "Jagt den listigen Wichtel und holt das Grimoire der arkanen Herangehensweisen zurück.", progress = "War Erzmagier Lan'dalock nützlich, {name}?", completion = "Ich werde dafür sorgen, dass Malicia das Grimoire erhält, damit sie seine Geheimnisse aufdecken kann.\n\nIn der Zwischenzeit müssen wir uns im Schwarzen Tempel umsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42595] = { id = 42595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Shrine - Azsuna Water 01 - DGK" }
quests[42596] = { id = 42596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammentrieb der Bergschreiter", description = "Seid Ihr <derjenige, von dem/diejenige> von der; ich so viel gehört habe, <Fremder/Fremde>?\n\nAls das Scharmützel mit den Drogbar losging, sind einige der jungen Elche ausgerissen!\n\nIch kann sie nicht verfolgen, weil die anderen sonst vielleicht auch weglaufen.\n\nKönntet Ihr sie vielleicht zu uns zurückbringen?", sourceObjective = "Sucht 3 verängstigte Bergschreiter und bringt sie zurück in den Stall von Liza Sturmschreiter.", completion = "Danke, Freund des Hochbergs.", sourceObjectiveStatus = "unverified-source-field" }
quests[42597] = { id = 42597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odyns Ruf", description = "Odyn möchte Euch unverzüglich sprechen, <Lehnsherr/Lehnsherrin>.\n\nEr ist davon überzeugt, dass Ihr genug an Macht hinzugewonnen habt und nun bereit seid, den direkten Befehl über seine Armeen zu übernehmen. Er möchte sofort mit den Vorbereitungen beginnen.", sourceObjective = "Sprecht mit Odyn in der Himmelsfeste.", completion = "Es ist, wie ich es vorhergesagt habe. Ihr gewinnt an Macht hinzu und erweist Euch würdig.\n\nEs ist Zeit, dass Ihr den Befehl über meine Armeen übernehmt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42598] = { id = 42598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions der Himmelsfeste", description = "Ihr werdet schon bald eine der größten bestehenden Armeen anführen. Bevor aber meine Valarjar Euren Befehlen folgen, müsst Ihr Eure Führungsqualitäten unter Beweis stellen.\n\nSprecht mit den beiden Vrykulchampions, die mit Euch in diese Hallen gekommen sind, und sagt ihnen, dass es für Euch an der Zeit ist, Eure Pflicht als <Auserwählter/Auserwählte> Odyns zu erfüllen.", sourceObjective = "Heuert Ragnvald Drachenson und Finna Bjornsdottir an.", completion = "Ihr seid jetzt bereit, die Armeen zu befehligen. Lasst uns anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42601] = { id = 42601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Wir haben großes Glück, Archivarin Melinda begegnet zu sein. Sie ist gewissermaßen eine Besonderheit, weil nicht viele ihrer Art unseren Pfad gewählt haben. Noch einzigartiger ist die Tatsache, dass sie unsere Kunst gründlich studiert hat. Ihr Wissen wird unübertroffen sein.\n\nSprecht mit ihr und sucht ihren Rat. Mit ihrer Hilfe werden wir den Rat sicherlich stärken können.", sourceObjective = "Sprecht mit Archivarin Melinda in der Schreckensnarbe.", completion = "Ausgezeichnete Wahl, {name}. Archivarin Melinda wird in der Schreckensnarbe bleiben, also sprecht mit ihr, wenn Ihr die Klassenordenshalle weiter verbessern wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42602] = { id = 42602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Es wird Zeit, unsere frisch ausgebildeten Wichtel ins Feld zu schicken. Seht Euch die Schlachtpläne der Schreckensnarbe an und schickt Eure Champions und Trupps auf eine Routineerkundungsmission.", sourceObjective = "Benutzt die Schlachtpläne der Schreckensnarbe und schließt die Mission \"Trupps in Ausbildung\" ab.", completion = "Die Aufklärungsmission war noch erfolgreicher, als wir erwartet hatten, {name}. Unsere Truppen konnten Archivarin Melinda, eine brillante Strategin, retten.\n\nZum Dank hat sie angeboten, uns zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42603] = { id = 42603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen um jeden Preis", description = "Nun, da Ihr wisst, dass die anderen Hexenmeister bereit sind, unsere Sache zu unterstützen, können wir uns die Schlachtpläne der Schreckensnarbe zunutze machen, um wichtige Missionen überall auf den Verheerten Inseln zu absolvieren.\n\nWenn wir den Rat wieder aufbauen möchten, müssen wir zunächst seine vermissten Mitglieder finden.\n\nWir sollten Ritssyn und Calydus aussenden, damit sie die Diener der Brennenden Legion verhören. Sie haben vielleicht Informationen, mit denen wir die vermissten Ratsmitglieder finden können.", sourceObjective = "Benutzt die Schlachtpläne der Schreckensnarbe und schließt die Mission \"Wissen um jeden Preis\" ab.", progress = "Wie läuft die Mission?", completion = "Ritssyn und Calydus haben Informationen bekommen, aber aufgrund der Beschaffungsmethoden wissen wir nicht, wie verlässlich sie sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[42605] = { id = 42605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ragnvald Drachenson", sourceObjective = "Odyn hat also Euch zum Anführer gemacht? Dann bin ich dabei. Ich finde es im Allgemeinen nicht so klug, die Entscheidungen der Götter zu hinterfragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42606] = { id = 42606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Finna Bjornsdottir", sourceObjective = "Ich kämpfe gern an Eurer Seite, {name}. Ich habe gesehen, wozu Ihr fähig seid, und ich weiß, dass Ihr keine Angst vor dem Tod habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42607] = { id = 42607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Stahlstrom", description = "Ja, die Seelen, die es bis in diese Hallen schaffen, sind tapfer. Genau deswegen sind sie ja hier.\n\nAber Tapferkeit allein ergibt noch keine effektive Armee. Ihr braucht jemanden, der diesen zukünftigen Valarjar beibringt, diszipliniert zu kämpfen.\n\nSchickt Eure Champions zu Hauptmann Stahlstrom. Diese ungebärdigen Vrykulberserker fürchten zwar nicht den Tod. Aber vor Hjalmar Stahlstrom haben sie so viel Angst, dass sie Euren Befehlen gehorchen werden.", sourceObjective = "Verwendet das Auge von Odyn und schließt die Mission \"Hauptmann Stahlstrom\" ab.", progress = "Ist es erledigt, {name}?", completion = "Hervorragend. Hjalmar wird die Valarjar im Nu in Form bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42608] = { id = 42608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "<Freund/Freundin> hat eine mächtige, aber einsame Position inne. <Erster/Erste> eines Rats, dessen Mitglieder vermisst werden.\n\n<Freund/Freundin> muss aber nicht allein sein. Andere werden sich zur Macht von <Freund/Freundin> hingezogen fühlen und bereit sein, zu folgen, wenn <Freund/Freundin> vorangeht.\n\nFindet diejenigen, die helfen wollen, und nehmt ihren Treueschwur an.", sourceObjective = "Rekrutiert Calydus und Ritssyn Flammengroll.", completion = "Es will schon etwas heißen, wenn Ritssyn seine Position aufgibt und auf Eure Führung baut. Er muss davon überzeugt sein, dass Ihr der Schlüssel für den Wiederaufbau des Rates seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[42609] = { id = 42609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Hauptmann Stahlstrom ist eingetroffen. Ich würde Euch raten, mit ihm zu sprechen und dafür zu sorgen, dass die Valarjar bewaffnet und kampfbereit sind.\n\nWir brauchen mehr als nur Eure beiden Champions, wenn wir einen richtigen Krieg gegen die Legion starten wollen.", sourceObjective = "Sprecht mit Hauptmann Hjalmar Stahlstrom und bildet Aspiranten der Valarjar aus.", completion = "Wir machen gute Fortschritte. Schon bald werdet Ihr über eine respektable Armee verfügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42610] = { id = 42610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Wir haben den Übergriffen der Feinde schon viel zu lange tatenlos zugesehen. Jetzt, wo Ihr Euren Champions Truppen an die Seite stellen könnt, solltet Ihr sie auch in die Schlacht entsenden.\n\nEiner unserer Leute ist von Odyns Erzfeindin Helya gefangen genommen worden. Wenn es Euren Truppen gelingt, Einar den Runenmagier lebend zurückzubringen, kann er uns helfen, mächtige Runen zu verwenden und somit Eure Armeen zu verstärken.", sourceObjective = "Verwendet das Auge von Odyn und schließt die Mission \"Truppen im Feld\" ab.", progress = "Ich grüße Euch.", completion = "Ausgezeichnet! Durch die Kräfte des Runenmagiers werden Eure Armeen noch stärker!", sourceObjectiveStatus = "unverified-source-field" }
quests[42611] = { id = 42611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einar der Runenmagier", description = "Als Anführer schickt man nicht einfach nur Truppen in den Kampf. Ihr müsst auch Entscheidungen treffen, wie wir unsere Armeen ausbilden und verbessern können.\n\nSprecht mit Einar dem Runenmagier und teilt ihm mit, wie Ihr die Armeen entwickeln wollt.", sourceObjective = "Sprecht mit Einar dem Runenmagier.", completion = "Eine weise Entscheidung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42614] = { id = 42614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Svergan Sturmmantel", sourceObjective = "Ich habe genug Zeit im Jenseits verbracht. Zeigt mir einfach, wo der Feind ist, und ich werde ihn vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[42616] = { id = 42616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Dvalen Eisenrune", sourceObjective = "Ich hatte geschworen, Ulduar zu beschützen, und ohne Euch hätte ich versagt.\n\nIhr könnt auf mich zählen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42617] = { id = 42617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: König Ymiron", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[42618] = { id = 42618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thorim", sourceObjective = "Ihr habt wahren Mut in Ulduar bewiesen, {name}. Ich werde meinen Eid erfüllen und dem Ruf des Gjallarhorns folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42619] = { id = 42619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hodir", sourceObjective = "Danke für Eure Hilfe, {name}. Mit Freuden kämpfe ich an Eurer Seite in Odyns Armee.", sourceObjectiveStatus = "unverified-source-field" }
quests[42620] = { id = 42620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Arkavellus" }
quests[42622] = { id = 42622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeremonielle Trommeln", description = "Diese närrischen Kälber!\n\nSie haben sich schon wieder mit unseren zeremoniellen Trommeln davongemacht und behandeln sie wie... Spielzeuge, wie... normale Trommeln!\n\nKönntet Ihr mir helfen, sie wieder einzusammeln? Sie haben sie sicher überall in ganz Donnertotem liegen lassen, nachdem sie damit ihren Spaß hatten.", sourceObjective = "Findet 4 große, 4 mittlere und 4 kleine zeremonielle Trommeln in Donnertotem.", progress = "Könnt Ihr den Rhythmus spüren?", completion = "Sehr schön. Da sind sie ja! Ihr könnt sie gern spielen, aber stellt sie dann wieder hier ab, ja? Ihr habt mir sehr geholfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42623] = { id = 42623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraterie zahlt sich nicht aus" }
quests[42624] = { id = 42624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Flotte" }
quests[42627] = { id = 42627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ungesehene Klinge", description = "Sturmwind ist viel zu wichtig, um der Legion in die Hände fallen zu dürfen. Und ich traue Shaw oder seinen SI:7-Schergen nicht zu, die Hand alleine in den Griff zu bekommen.\n\nWir zwei werden uns darum kümmern müssen, solange noch Zeit ist.\n\nIhr müsst extrem vorsichtig sein. Die gesamte Stadt ist bereits nervös wegen der Gerüchte über die Aktivitäten des Kultes, und uns droht dort auch unter normalen Umständen schon der Tod.\n\nDie anderen Schatten haben in den höchsten Tönen von Euren Fertigkeiten gesprochen. Seid Ihr dabei?", sourceObjective = "Helft Garona, die Kultisten der Verschleierten Hand in Sturmwind auszuschalten.", completion = "Jeder Augenblick, den ich diese Klingen wieder hielt, war die reinste Qual. Sie gehören ganz Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42628] = { id = 42628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 046 - Dreyrgrot" }
quests[42629] = { id = 42629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 047 - Dreyrgrot" }
quests[42630] = { id = 42630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolabombardement", description = "Ich habe gehört, dass ein Zirkel Harpyien mit ihren Rocs einen groß angelegten Angriff plant.\n\nSie werden von den Bergen im Norden aus herabstoßen.\n\nSchnappt Euch einen der Bolawerfer. Ich nehme den anderen.\n\nSchnell!", sourceObjective = "Tötet 42 Angreifer des Zirkels.", progress = "Zeigt diesen Harpyien, dass sie nicht einmal daran denken sollten, Donnertotem anzugreifen!", completion = "Gute Arbeit da draußen, {name}. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[42631] = { id = 42631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Inquisitor Tivos" }
quests[42632] = { id = 42632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 048 - Dreyrgrot" }
quests[42633] = { id = 42633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorthax" }
quests[42634] = { id = 42634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konfrontation am Schwarzen Tempel", description = "Lan'dalocks Buch ist sehr aufschlussreich. Es beschreibt eine Technik, mit deren Hilfe man leicht und elegant die heilige Barriere des Schwarzen Tempels umgehen kann.\n\nIch brauche einen Moment, um ein Tor zu beschwören. Bleibt bitte zurück.", sourceObjective = "Benutzt das Tor zum Schwarzen Tempel und konfrontiert Akama.", completion = "Wer hätte geglaubt, dass er mit uns gemeinsame Sache machen würde?\n\nJetzt sind wir unserem Ziel einen Schritt näher gekommen, den Kampf gegen die Brennende Legion in ihre eigenen Welten zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42635] = { id = 42635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis von Dreyrgrot", description = "Seid gegrüßt!\n\nIch war auf dem Weg, um die örtlichen Murlocs zu studieren, als ich über ein paar sehr seltsame Ruinen gestolpert bin. Allerdings sind diese Piraten dort hinten vor uns eingetroffen und haben augenscheinlich irgendein uraltes böses Wesen freigelassen.\n\nEin solch bösartiges Geschöpf darf nicht frei herumlaufen, aber vielleicht sollten wir erst etwas darüber in Erfahrung bringen, damit wir nicht wie diese Kerle enden.\n\nIch habe beobachtet, wie die Crew ein paar Tafeln aus den Ruinen geholt hat. Wenn Ihr mir diese Tafeln bringen könnt, werde ich versuchen, dieses bösartige Wesen zu identifizieren.", sourceObjective = "Beschafft 4 uralte Schrifttafeln von Dreyrgrot von den Piratenschiffen außerhalb von Dreyrgrot.", progress = "Wie läuft die Jagd nach Wissen?", completion = "Ausgezeichnet! Zum Glück habe ich eine Abschrift des Vrykulschlüssels mitgebracht, den die Forscherliga aus Nordend beschaffen konnte.\n\nIch werde mich sogleich an die Arbeit machen! Hoffen wir, dass sich die Dialekte nicht allzu sehr unterscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42636] = { id = 42636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Arkanist Shal'iman" }
quests[42637] = { id = 42637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42638] = { id = 42638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42639] = { id = 42639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein blutiger Stein", description = "Leider haben wir vielleicht noch ein weiteres Problem. Der aus den Ruinen aufsteigende Nebel scheint die plündernden Piraten befallen und sie gehörig in den Wahnsinn getrieben zu haben.\n\nNur einer von ihnen ist offensichtlich nicht davon betroffen: ein Kerl mit einem schneidigen Hut, bei dem es sich um einen Kapitän zu handeln scheint. Um den Hals trägt er ein Rubinamulett, das ihn meiner Meinung nach vor dem Nebel schützt. Wenn Ihr die Grabstätte betreten wollt, braucht Ihr dieses Amulett.\n\nAber er wird es wohl nicht freiwillig herausrücken.", sourceObjective = "Holt Bruchzahns Rubinamulett von Kapitän Bruchzahn auf den Schiffen nahe Dreyrgrot.", progress = "Um fortfahren zu können, benötigen wir den Schutz des Amuletts.", completion = "Ihr habt das Amulett! Ganz ausgezeichnet!\n\nNatürlich bietet dies keine Hilfe im Kampf gegen die schon dem Wahnsinn anheimgefallenen Piraten, aber dennoch ist es ein kleiner Erfolg, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[42640] = { id = 42640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wert des Wissens", description = "Diese Kiste ist voller Relikte aus den Ruinen in der Nähe. Die Piraten haben offensichtlich ihren Wert nicht erkannt und sie einfach entsorgt.\n\nMeine Kollegen aus der Forscherliga würden es sicher zu schätzen wissen, wenn Ihr diese Relikte bergen und ihnen zu Studienzwecken überlassen könntet.", sourceObjective = "Bergt 7 Kisten mit uralten Relikten aus den Gewässern vor Dreyrgrot.", progress = "Was haben wir denn hier?", completion = "Das war wirklich eine edle Tat von Euch, diese uralten Relikte aus dem Wasser zu retten.\n\nIch werde dafür sorgen, dass die Forscherliga gewissenhaft mit ihnen umgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42641] = { id = 42641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Knochensprechern begraben", description = "Wahrlich faszinierend! Anscheinend haben wir es mit unserem ganz persönlichen Vrykulvampyr zu tun!\n\nBis jetzt sind uns immer nur solche begegnet, die von den Blutelfen abstammten, aber es gibt schon seit Langem die Theorie, dass auch Vrykul von diesem Fluch betroffen werden können. Schade, dass er bereits wach ist. Ich würde ihn zu gern in Ruhe untersuchen.\n\nAber wir haben wohl keine andere Wahl. Nehmt diesen Pflock und jagt ihn durch sein Herz. Das sollte ihm aller Wahrscheinlichkeit nach den Rest geben.", sourceObjective = "Verwendet den spitzen Holzpflock, um Blutthan Lucard in Dreyrgrot zu töten.", completion = "Oh, der Pflock hat nicht funktioniert, sagt Ihr? Tut mir leid, da muss ich wohl die Methoden für verschiedene üble Unsterbliche verwechselt haben.\n\nAber Ihr seid ja noch in einem Stück und die böse Kreatur ist endlich tot. Hoffe ich zumindest.\n\nVampyre können doch sterben, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[42645] = { id = 42645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böses Blut", description = "Der Tod des Blutprinzen wird ein Segen für dieses Land sein, aber wir können nicht zulassen, dass diese verrückten Korsaren hier Amok laufen. Ich fürchte, dass wir sie dem Schwert überantworten müssen.\n\nWenn Ihr diese edle Pflicht erfüllt, werde ich Euch gern mit einem schönen warmen Bier belohnen.", sourceObjective = "Tötet 8 blutgierige Schwadroneure in Dreyrgrot.", completion = "Niemand wird ihnen eine Träne nachweinen.\n\nDiese Kerle waren schon eine Plage, bevor sie wahnsinnig geworden sind. Man stelle sich nur vor, was sie angestellt hätten, wenn Ihr sie nicht aufgehalten hättet!\n\nEure Tapferkeit ist wirklich bemerkenswert!", sourceObjectiveStatus = "unverified-source-field" }
quests[42646] = { id = 42646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medical Supply Crate" }
quests[42647] = { id = 42647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medical Supply Crate" }
quests[42648] = { id = 42648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medical Supply Crate" }
quests[42649] = { id = 42649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arluin Bribe Tracker 2" }
quests[42650] = { id = 42650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bande durchtrennen", description = "Die Mystiker der Knochensprecher haben diese Erbstücke benutzt, um meine Seele an diese Welt zu binden.\n\nUnter dem Einfluss ihres Fluchs konnte meine Seele nicht in die Hallen der Tapferkeit einziehen. Sucht nach dem Scheiterhaufen der Seelen in Haustvald und übergebt meine Habseligkeiten den Flammen.\n\nDas Feuer, das meine Seele durch ihre widerwärtige Magie gebunden hat, wird dasselbe Feuer sein, das dieses Band durchtrennt!", sourceObjective = "Werft Svergans Habseligkeiten auf den Scheiterhaufen der Seelen und schließt das Ritual der Entfesselung ab.", progress = "Ist es schon vollbracht, SHAZEI?", completion = "Ich kann es spüren. Meine Seele gehört wieder mir allein!", sourceObjectiveStatus = "unverified-source-field" }
quests[42651] = { id = 42651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svergans Versprechen", description = "Danke, dass Ihr das für mich getan habt. Ich habe einen Eid geschworen, das Gjallarhorn mit meinem Leben zu schützen, und das habe ich auch getan.\n\nIhr müsst Hymdall sagen, dass sein Gjallarhorn vom großen Wurm Jorhuttam verschlungen wurde!\n\nEr hat eine ganze Armee meiner Männer vernichtet. Er hat sie in einem Stück hinuntergeschluckt, während sie versuchten, die Bestie zu bekämpfen. Findet Jorhuttam und Ihr werdet das Horn finden!", sourceObjective = "Kehrt zu Hymdall in der Himmelsfeste zurück.", completion = "Jorhuttam! Wir müssen den großen Wurm umgehend aufspüren. Das wird sicherlich ein gewaltiger Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[42652] = { id = 42652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Exemplare" }
quests[42653] = { id = 42653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Akama", sourceObjective = "Es ermutigt mich, dass wir zu einer Verständigung kommen konnten. Ich bewunderte Altruis, als er sich vor all diesen Jahren gegen die von Illidan eingeschlagene Richtung auflehnte. Die Vernichtung der Brennenden Legion ist unser wichtigstes Ziel, aber wir dürfen dabei nicht zu dem werden, was wir zu zerstören hoffen.\n\nWenn Ihr mich als Champion erwählt, werde ich der Sache mit all meinem Wissen dienen. Ich glaube sogar, dass wir uns nach einer gewissen Zeit gegenseitig vertrauen werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[42654] = { id = 42654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Alptraumeichenholz", description = "Schmied Kyriel ist den Weltenwanderern gut bekannt. Er hat in der Vergangenheit zahllose Pfeilspitzen für uns geschmiedet und mithilfe seines Wissen um besondere Materialien bessere und wirkungsvollere Munition hergestellt.\n\nEr ist effizient und talentiert und versteht es, das Beste aus den wenigen verfügbaren Materialien zu machen.\n\nAus einem einzigen Ast eines verderbten Urtums kann er Tausende Pfeile herstellen.", sourceObjective = "Besorgt Alptraumeichenholz von Eichenherz im Finsterherzdickicht.", progress = "Habt Ihr schon das Eichenholz eingesammelt?", completion = "Aus einem kleinen bisschen Eiche kann man jede Menge Munition herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42655] = { id = 42655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erz unter dem Meer", description = "Wenn wir den Kampf zu Hakkar tragen wollen, werden meine Waldläufer Pfeile und Munition brauchen, mit denen sie die dicken, magieresistenten Felle dieser Hunde durchdringen können.\n\nEs gibt einen vielseitigen Schmied in Dalaran, der ganz außergewöhnliche Bögen und Schwerter herstellt.\n\nFür seine Kreationen verwendet er Azurerz, das man nur unter Wasser findet.\n\nDa es in der Nähe von Leystein vorkommt, wird das Erz oft übersehen, aber ein Schmiedeexperte kann es zu etwas nahezu Unzerstörbarem verarbeiten.", sourceObjective = "Baut Azurerz von Vorkommen im Wasser vor der Küste Suramars ab.", progress = "Habt Ihr das Erz schon abgebaut?", completion = "Ich glaube, das ist mehr als genug, um Waffen und Munition für unsere Verbündeten herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42656] = { id = 42656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurwaffen", description = "Bringt die Materialien zu Schmied Kyriel in Dalaran. Er wird damit so viele Waffen herstellen, wie er kann.\n\nWie ich bereits sagte, ist er geschickt und effizient, also solltet Ihr nicht lange warten müssen.\n\nWenn er mit seiner Arbeit fertig ist, sprecht mit Shandris Mondfeder darüber, wie Ihr die Waffen verzaubern lassen könnt.", sourceObjective = "Findet Schmied Kyriel in Dalaran.", progress = "Wir werden besondere Waffen benötigen, wenn wir Hakkar und seine Hunde vernichten wollen.", completion = "Haldurons Schmied leistet hervorragende Arbeit, aber diese Waffen müssen erst verzaubert werden, bevor sie gegen Hakkars Hunde Wirkung zeigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[42657] = { id = 42657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen im Mondklauental", description = "Lyana Sternenstaub hält sich immer noch in einem Tal auf, das von Dämonen überrannt wurde. Trotz der aktuellen Lage weigert sie sich, ihr Zuhause zu verlassen.\n\nDie Stärke und Unbeugsamkeit, die sie im Angesicht des Feindes an den Tag legt, sind Charaktereigenschaften, die sich auch in ihren Verzauberungen widerspiegeln.\n\nWir wollen, dass unsere Waffen genauso stark und unbeugsam sind wie sie.\n\nTrefft Euch mit ihr im Mondklauental und seht, ob sie ihre Magie auf die Waffen übertragen kann, die Kyriel für uns hergestellt hat.", sourceObjective = "Findet Lyana Sternenstaub in Val'sharah.", completion = "Die Schildwachen sagten mir, dass Ihr kommen würdet.\n\nBitte entschuldigt den Zustand meines Zuhauses. Ich hatte kürzlich Ärger mit ungebetenen Gästen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42658] = { id = 42658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heikle Verzauberungen", description = "Wie Ihr sicher bemerkt habt, wurde das Tal von Dämonen übernommen. Ihre Ankunft hat viele meiner Druidenkollegen zur Flucht aus ihren Heimstätten gezwungen, aber ich weigere mich, kampflos aufzugeben.\n\nTrotz allem werde ich gerne Eure Waffen verzaubern, aber Ihr solltet wissen, dass dieser schwierige Vorgang Zeit und Konzentration braucht und beides in letzter Zeit bei mir Mangelware ist.\n\nWenn Ihr mich vor meinen Angreifern schützt, werde ich mein Bestes geben, um Eure Waffen zu verzaubern.", sourceObjective = "Beschützt Lyana Sternenstaub, während sie die Azurwaffen verzaubert.", progress = "Es wird eine Menge Macht und hohe Konzentration erfordern, um Eure Waffen zu verzaubern.", completion = "Wenn ich Euch überreden könnte, zu bleiben, würde ich viel mehr Arbeit erledigen können, aber ich weiß, dass Ihr dringend anderswo gebraucht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[42659] = { id = 42659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung Dalarans", description = "Wir haben alles Notwendige, um Hakkar eine Falle zu stellen.\n\nErzmagier Khadgar wird ein Portal zur Violetten Festung beschwören. Sobald Ihr dort drinnen seid, wird er auf Euren Befehl hin seine Essenz in ein arkanes Gefäß kanalisieren.\n\nUnsere Verbündeten werden mit den Waffen ausgerüstet sein, die Ihr ihnen gebracht habt, und sie werden kampfbereit sein, wenn Hakkar den Köder schluckt.", sourceObjective = "Betretet die Violette Festung durch Khadgars Portal und besiegt Hakkar den Hundemeister.", completion = "Ich bin ja so erleichtert, Euch zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42660] = { id = 42660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Herzensangelegenheiten", description = "Ich habe mit dem Blutstein bereits große Fortschritte gemacht. Das verdanke ich zum Teil auch Euren ausgiebigen Tests.\n\nDer Stein nährt sich im Grunde an Blut, um seine Kräfte zu mehren, aber seine Kontrolle über einen Dämon erlangt er dadurch, dass er ein verderbtes Herz aufzehrt. Je mächtiger dieses Herz, desto besser.\n\nIm Verlies der Wächterinnen findet Ihr ein solches Herz.", sourceObjective = "Besorgt ein Dämonenpaktherz von Cordana im Verlies der Wächterinnen.", progress = "Die Macht des Blutsteins wird enorm wachsen, nachdem er Cordanas Herz aufgezehrt hat.", completion = "Sobald das Herz aufgezehrt ist, wird der Blutstein stark genug sein, um die Eredarschwestern zu kontrollieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42662] = { id = 42662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Erzmagier Kalec", sourceObjective = "Der blaue Drachenschwarm stand immer für die Magie auf Azeroth, und so ist es nur recht und billig, dass wir gegen die Brennende Legion zusammenarbeiten. Es wäre mir eine Ehre, in diesen finsteren Zeiten als Euer Champion zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42663] = { id = 42663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Die Tirisgarde gibt es schon seit Ewigkeiten nicht mehr. Wenn wir die Brennende Legion bezwingen wollen, müssen wir erst die mächtigsten Champions unserer Klasse rekrutieren, um an unserer Seite zu kämpfen. Zwei mächtige Erzmagier, Erzmagier Kalec und Erzmagierin Modera, sind zu uns gekommen, um unseren Erfolg zu unterstützen.\n\nSprecht mit ihnen und sichert uns ihre Hilfe.", sourceObjective = "Rekrutiert Erzmagier Kalec und Erzmagierin Modera.", completion = "Erzmagier Kalec und Erzmagierin Modera gehören zu den größten Magiern der Geschichte Azeroths. Sie werden leuchtende Vorbilder für unseren Orden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42664] = { id = 42664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Akamas Schemen", sourceObjective = "Ich habe Illidans kompromisslose Entschlossenheit immer bewundert. Schließlich ist die Vernichtung der Brennenden Legion von höchster Bedeutung. Alles andere ist unwichtig. Nichts darf sich uns dabei in den Weg stellen.\n\nIhr werdet mich als Euren Champion auserwählen. Im Gegenzug werde ich der Sache mit all meinem Wissen dienen. Bald werden wir all unsere Feinde vernichtet haben... vielleicht sogar auch Akama?", sourceObjectiveStatus = "unverified-source-field" }
quests[42665] = { id = 42665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In unsere Reihen", description = "Ich finde, wir sollten viel Aufhebens darum machen, dass wir Akamas Schemen in unserer Mitte aufnehmen. Die anderen müssen unbedingt sehen, dass er als einer von uns behandelt wird und nicht als Außenseiter.\n\nKor'vas Blutdorn hat immer wieder unter Beweis gestellt, dass sie von unschätzbarem Wert ist. Ihre Kampffertigkeiten sind unbestreitbar und beispiellos. Ihr werdet keinen besseren Champion finden, um unsere Feinde zu vernichten.\n\nEs wird Zeit, sie offiziell als Champions anzuerkennen.", sourceObjective = "Rekrutiert Akamas Schemen und Kor'vas Blutdorn als Eure Champions.", completion = "Bisher waren die Illidari ein ziemlich exklusiver Verein. Ausschließlich {class}. Doch wie Ihr so deutlich gezeigt habt, mein Lieber, ist die Aufnahme von Akama ein wichtiger Schritt, um voranzukommen und uns gegenseitig vertrauen zu können.\n\nDas gibt Hoffnung.\n\nUnd es versteht sich natürlich von selbst, dass Ihr Kor'vas zu einem Eurer Champions macht. Niemand kämpft so gut wie sie.\n\nWas ist da los?", sourceObjectiveStatus = "unverified-source-field" }
quests[42666] = { id = 42666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Teufelshammer zurück.", description = "{name}, Schlachtenfürst Gaardoun hat mich angewiesen, nach Euch zu suchen. Er sagte, er bräuchte Eure Hilfe in einer sehr wichtigen Angelegenheit.\n\nEr möchte, dass Ihr so schnell wie möglich auf die Teufelshammer kommt.", sourceObjective = "Sprecht mit Schlachtenfürst Gaardoun auf der Teufelshammer.", completion = "Kommandant, ich bin froh, dass Asha Euch so schnell ausfindig machen konnte.\n\nEs gibt eine Sache, um die Ihr Euch so schnell wie möglich kümmern müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[42669] = { id = 42669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionsvorbereitungen", description = "Wir haben den Sargeritschlüsselstein und den Großteil der Streitkräfte, die wir benötigen. Wir haben sogar einen Plan.\n\nJetzt müssen wir die Teufelsseelen ausfindig machen und uns auf die Invasion der Dämonenwelt vorbereiten, auf der sie sich verkrochen haben.\n\nBitte überlasst mir das. Wenn Ihr mir erlaubt, Eure Champions zu befehligen, dann werden ich und die Seelensense die Informationen um jeden Preis aus den Dämonen herausbekommen.", sourceObjective = "Benutzt die Späherkarte und schließt die Missionen der Reihe \"Invasionsvorbereitungen\" ab.", completion = "Jetzt wissen wir, dass Caria und Varedis sich auf der als Niskara bekannten Dämonenwelt verkrochen haben.\n\nZeit, die Sache zu Ende zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42670] = { id = 42670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Die Matronenmutter, Lady S'theno und ich haben Euch und die anderen Illidari beobachtet. Da wir die Dinge von außen betrachten, ist uns eine gewisse Objektivität zu eigen. Wir sind zu einer einstimmigen Empfehlung gelangt: Um ein Zersplittern der Illidari zu verhindern, müsst Ihr anfangen, Champions zu rekrutieren.\n\nDiese wenigen Auserwählten werden dabei helfen, Eurer Macht über die Grenzen der Teufelshammer hinaus Geltung zu verschaffen.\n\nWir empfehlen einstimmig, als Erstes Altruis und Asha auszuwählen.", sourceObjective = "Rekrutiert Altruis den Leidenden und Asha Rabenruf als Eure ersten Champions.", completion = "Ihr habt Eure ersten beiden Champions ausgewählt. Vor uns liegen großartige Taten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42671] = { id = 42671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Die Matronenmutter, Lady S'theno und ich haben Euch und die anderen Illidari beobachtet. Da wir die Dinge von außen betrachten, ist uns eine gewisse Objektivität zu eigen. Wir sind zu einer einstimmigen Empfehlung gelangt: Um ein Zersplittern der Illidari zu verhindern, müsst Ihr anfangen, Champions zu rekrutieren.\n\nDiese wenigen Auserwählten werden dabei helfen, Eurer Macht über die Grenzen der Teufelshammer hinaus Geltung zu verschaffen.\n\nWir empfehlen einstimmig, als Erstes Kayn und Asha auszuwählen.", sourceObjective = "Rekrutiert Kayn Sonnenzorn und Asha Rabenruf als Eure ersten Champions.", completion = "Ihr habt Eure ersten beiden Champions ausgewählt. Vor uns liegen großartige Taten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42673] = { id = 42673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kor'vas Blutdorn", sourceObjective = "Das wurde auch Zeit, Dummerchen! Als Ihr Asha Rabenruf zuerst gewählt habt, kamen mir für einen Moment Zweifel an Eurem Geisteszustand.\n\nNicht, dass mit Asha etwas nicht stimmen würde. Aber wir wissen doch beide, wer der bessere Kämpfer ist.\n\nOder?\n\nJedenfalls ist es mir natürlich eine Ehre, Euer Champion zu sein. Ich nehme an!", sourceObjectiveStatus = "unverified-source-field" }
quests[42677] = { id = 42677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Gaardoun so braucht", description = "Schlachtenfürst Gaardoun hat angeboten, weitere zerschlagene Krieger für die Sache anzuwerben. Er benötigt vorher aber ein paar Dinge. Er erwähnte so etwas wie das richtige Werkzeug für die Aufgabe, oder sowas.\n\nEs wird Zeit, unsere frischgebackenen Champions auf die Probe zu stellen. Ich bin sicher, es wird eine aufreibende Mission.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Was Gaardoun so braucht\" ab.", completion = "Nun, immerhin werden wir hier ein paar neue Gesichter zu sehen bekommen. Soweit man das Gesicht eines Zerschlagenen als neu bezeichnen kann...\n\n<Kor'vas grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42678] = { id = 42678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Zur Rabenwehr", description = "Dieses Ding ist uralt. Es droht sich in meinen Händen aufzulösen, wenn ich auch nur die Seiten umblättere.\n\nHier, ich habe es gefunden. Ein Eintrag über das Rabenauge.\n\n<Valeera fährt mit dem Finger von links nach rechts über die Seite. Plötzlich huscht ein Ausdruck der Erkenntnis über ihr Antlitz, kurz darauf runzelt sie die Stirn.>\n\nHier steht, dass die letzte Person im Besitz des Auges Lord Rabenkrone persönlich war. Ihr werdet in die Rabenwehr gehen müssen, um es ihm abzunehmen.", sourceObjective = "Stellt eine Gruppe zusammen und betretet die Rabenwehr, um das Rabenauge von Dantalionax zu holen.", progress = "{name}, hattet Ihr Erfolg? Habt Ihr das Rabenauge?", completion = "Wir haben es. Endlich werden wir in der Lage sein, den Code des Briefs vom SI:7 zu knacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[42679] = { id = 42679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieger der Zerschlagenen", description = "Es ist wichtig, dass wir unsere Truppenzahl aufstocken. Glaubt mir, ich weiß, wovon ich spreche. Schlachtenfürst Gaardoun und seine Krieger der Aschenzungen bieten uns die beste Chance, das schnell zu erreichen.\n\nIhr solltet mit ihm reden und ihn wissen lassen, welche Zerschlagenen für Euch ausgebildet werden sollen.", sourceObjective = "Sprecht mit Schlachtenfürst Gaardoun und bildet Krieger der Aschenzungen aus.", progress = "Wie machen sich die neuen Truppen der Aschenzungen?", completion = "Hervorragend. Diese neuen Aschenzungen werden Euch die Flexibilität geben, die Ihr braucht, um Truppen überall dort einzusetzen, wo Ihr sie braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42680] = { id = 42680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlüsseln des Briefes", description = "Wir haben das Rabenauge. Benutzt es, {name}. Dechiffriert den Brief vom SI:7.\n\nWir müssen wissen, welche Geheimnisse er enthält!", sourceObjective = "Benutzt das Rabenauge, um den verschlüsselten Brief vom SI:7 zu dechiffrieren.", progress = "Wieso zögert Ihr? Dechiffriert den Brief.", completion = "Ich muss zugeben, das habe ich nicht erwartet. Mathias Shaw wurde von der Legion gefangen genommen.\n\nDas erklärt immerhin die merkwürdigen Aktionen des SI:7 in letzter Zeit. Ein Schreckenslord steht an ihrer Spitze.", sourceObjectiveStatus = "unverified-source-field" }
quests[42681] = { id = 42681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus, seid Ihr das?", description = "Belath Dämmerklinge hat uns einen merkwürdigen Späherbericht vom Teufelsfeuervorstoß in Azsuna übermittelt. Schreckenslord Razelikh der Entweiher ist in die Welt zurückgekehrt. Das ist allerdings nicht der seltsame Teil.\n\nEigenartigerweise tötet er manchmal andere Dämonen und nennt sich selbst Loramus!\n\nUnseres Wissens nach hatte sich unser Dämonenjägerbruder Loramus Thalipedes geopfert, um Razelikh, der von ihm Besitz ergriffen hatte, zu besiegen.\n\nEure Champions und die Krieger der Aschenzungen müssen sich nach Azsuna begeben und herausfinden, was da vor sich geht.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Loramus, seid Ihr das?\" ab.", completion = "Sie haben ihn mit zurückgebracht. Es ist auf jeden Fall Loramus. Doch er ist im Körper des als Razelikh der Entweiher bekannten Schreckenslords gefangen!\n\nBis wir sicher sein können, dass er keine Gefahr darstellt, habe ich befohlen, ihn in einer unserer Dämonenfallen unten festzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42682] = { id = 42682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche Requisiten", description = "Mir ist das Gerücht zu Ohren gekommen, dass Ihr den Versuch unternehmen wollt, mit Illidans unsterblicher Dämonenseele im Wirbelnden Nether Kontakt aufzunehmen. Ihr werdet viele magische Dinge benötigen.\n\nIch habe mir die Mühe gemacht, eine Liste möglicher Gegenstände für Euch aufzustellen. Ich hoffe sehr, dass sie nützlich sein wird, <mein Hübscher/meine Hübsche>.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Zusätzliche Requisiten\" ab.", progress = "Sind sie schon mit allem, was wir für das Ritual benötigen, zurückgekommen?", completion = "Brauchen wir wirklich all diese Zutaten, um die Seele des Meisters anzurufen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42683] = { id = 42683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Verbesserungen", description = "Die Rückkehr von Loramus wird sich sehr zu unserem Vorteil auswirken, obwohl er in Razelikhs Körper gefangen ist... und obwohl der Dämon manchmal die Oberhand gewinnt.\n\nEr war dennoch einer unserer besten Dämonenjäger. Und jetzt verfügt er zusätzlich noch über das Wissen eines Schreckenslords.\n\nIch glaube, wir sollten dafür sorgen, dass er sein Wissen und seine Weisheit mit uns teilt, um unsere Chancen in diesem Krieg zu verbessern.", sourceObjective = "Hört Euch Loramus Thalipedes' Geschichte an und verbessert dann Eure Klassenordenshalle.", progress = "Was hatte Loramus der Schreckenslord zu sagen?", completion = "Das klingt nach guten Neuigkeiten. Er trägt bereits zu unserer Sache bei und wir sind durch seine Hilfe viel stärker.\n\nTrotzdem hat er Razelikh noch nicht völlig unter Kontrolle. Ich denke, es wäre das Beste, wenn wir ihn in dieser Falle lassen, bis wir einen neuen Körper für ihn gefunden haben. Meint Ihr nicht auch?\n\nUnd wenn er ein zu großes Problem darstellen sollte, können wir auch noch... \"andere\" Maßnahmen ergreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42684] = { id = 42684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 abschütteln", description = "Der SI:7 sitzt uns ständig im Nacken. Wir müssen sicherstellen, dass sie von unserem Tun keinen Wind bekommen.\n\nZu diesem Zweck habe ich ein paar Vorschläge für Euch in Form von Missionen. Schickt Eure Champions aus, entsendet Eure Streitkräfte, das ist mir ziemlich egal. Das Wichtige ist, dass wir sie aus Val'sharah und von der Rabenwehr fernhalten.\n\nWenigstens bis wir diesen verfluchten Brief entziffert haben.", sourceObjective = "Benutzt die Späherkarte und schließt die Missionen der Reihe \"SI:7 abschütteln\" ab.", completion = "Überraschend gute Arbeit. Nach dem, was mir meine Späher berichten, funktionieren die Ablenkungsmanöver ausgesprochen gut.\n\nAls zusätzlicher Bonus wurden einige meiner Verdachtsmomente im Zusammenhang mit einem gewissen Gegenstand in Sturmheim, der sich beim Dechiffrieren des Briefs vom SI:7 als sehr nützlich erweisen würde, als richtig erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42685] = { id = 42685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Erzmagierin Modera", sourceObjective = "Gut, dass sich die Tirisgarde wieder erhebt, {name}. Es sind zwar nicht alle Mitglieder des Rates der Sechs meiner Meinung, doch ich halte es für unerlässlich, dass wir zusammenarbeiten und die Legion ein für alle Mal besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42687] = { id = 42687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Unsere Truppen sind bereit! Jetzt ist es an der Zeit, sie im Feld zu prüfen.\n\nWir haben von einigen Überlebenden nahe der Verheerten Küste gehört, aber das gesamte Gebiet ist immer noch von der Legion überrannt.\n\nEntsendet unsere Truppen so schnell wie möglich auf eine Rettungsmission!", sourceObjective = "Schließt die Mission \"Truppen im Feld\" ab.", completion = "Wir hatten großes Glück, Chronistin Elrianne unter den Überlebenden zu finden. Sie ist eine respektierte Archivarin der Kirin Tor, die außerdem einige Monate lang mit den Pandaren in der Bibliothek des Tianklosters studiert hat.\n\nIhr Wissen über uralte Magie wird für unseren Orden unschätzbar wertvoll sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42688] = { id = 42688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mrgls der Zärtlichkeit", description = "Mrmlgr! Mrglr rlmgrg mlrgr! Mrlgmr...\n\n<Phin zeigt Euch einen Makel an der Perle.>\n\nMmlrgmlr rlmgr grlmrmlg mglrmglr. Mlrgmrl rmglr? Mlgrmglr!\n\nGmmlrgmrl mlrgmlr lrglrmgrl lrlgllrlm mglrlr grlm-grlm.\n\n<Phin macht eine Zwickbewegung mit seiner Hand.>\n\nMrlgmlgr mgrlmlgr? Mlrgmlr gmrlmglr Mrgrlilgrl." }
quests[42689] = { id = 42689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Feind kennen", description = "Wenn es uns gelingen soll, die Oberhand über Hakkar zu gewinnen, dann müssen wir mehr über die von ihm gezüchteten Hunde herausfinden und ihre Schwächen genau ausmachen.\n\nIch weiß von einer Hexenmeisterin, die sich ausführlich mit Dämonen beschäftigt. Vielleicht hat sie schon einige dieser Hunde gesehen und weiß, wie man sie besiegen kann.", sourceObjective = "Sprecht mit Kira Zornseele in Azsuna.", completion = "In Faronaar wimmelt es nur so von Dämonen. Einige sind uns bekannt, andere eher sonderbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[42690] = { id = 42690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Altruis der Leidende", sourceObjective = "Ihr ehrt mich, {name}. Selbstverständlich werde ich als Euer Champion und rechte Hand dienen. Wie könnte ich das ablehnen?\n\nWir haben gerade erst damit begonnen, die Handlungsweise der Illidari zu verändern, und Ihr habt große Fortschritte erzielt. Wenn wir die Brennende Legion besiegen wollen, müssen alle eng zusammenarbeiten. Die Illidari dürfen nicht allein dastehen.\n\nUnd außerdem wird es kein echter Sieg sein, wenn wir am Ende auf den rauchenden Trümmern einer Welt stehen, die wir aus Nachlässigkeit zerstört haben, als wir sie doch retten wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42691] = { id = 42691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leywurmköder", description = "Teufelshunde fühlen sich von Magie angezogen, besonders die jungen.\n\nSie brauchen sie nur kurz zu schnuppern und verfallen in einen Fressrausch! Ihr seid nicht ganz so anziehend wie ein Magier, also müsst Ihr Euch etwas überwerfen, das einen Teufelshund denken lässt, dass Ihr seine nächste Magiemahlzeit seid.\n\nLeywurminnereien sollten genau das Richtige sein.", sourceObjective = "Sammelt Leywurminnereien von Würmern in der Leygrotte in Azsuna.", progress = "Leywurminnereien stecken voller magischer Substanzen, die für Teufelshundnestlinge unwiderstehlich sind.", completion = "Diese Innereien strotzen vor Magie. Dadurch geben sie ausgezeichnete Köder ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[42692] = { id = 42692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinder von Nar'thalas", description = "Hallo! Ihr seid {name}, richtig? Die Erzmagier in Dalaran erwähnten, dass Ihr vielleicht hier unten auftauchen würdet.\n\nMein Bruder und ich sind hier auf einer Aufklärungsmission unterwegs. Wir suchen nämlich nach unseren Eltern.\n\nUnser ganzes Leben lang hatten wir geglaubt, dass unsere Familie vor einigen tausend Jahren in Azsuna getötet worden sei. Aber seht selbst: Die meisten Elfen hier sind Geister.\n\nOlothil hat die Bücher auf der Suche nach Hinweisen studiert, aber wir könnten etwas Hilfe brauchen.", sourceObjective = "Sucht nach drei uralten Folianten der Hochgeborenen in den Ruinen von Nar'thalas.", progress = "Wir kommen hier nicht weiter. Wie sieht es bei Euch aus?", completion = "Dieser Prinz Farondis hat sich Königin Azshara entgegengestellt, und deswegen war sie so wütend, dass sie alles zerstört hat? Unglaublich!\n\nHey, Olothil, hör dir das mal an!", sourceObjectiveStatus = "unverified-source-field" }
quests[42693] = { id = 42693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellsicht ist besser als Nachsicht", description = "Wenn ich die Geister unserer Familie finden will, benötige ich Materialien, um ihren Aufenthaltsort wahrzusagen.\n\nDiese Naga besitzen von Leyenergie erfüllte magische Schmuckstücke. Die sind besser auf dieses Land abgestimmt als alles, was wir in Dalaran haben. Mit ein paar davon könnte ich richtige Hellseherei leisten.", sourceObjective = "Besorgt 3 Glypten der Hassnattern.", progress = "Ich hätte meinen eigenen Zauberfokus mitgebracht, wenn nicht EIN GEWISSER JEMAND so gedrängelt hätte...", completion = "Perfekt. Wollen wir also mit dem Ritual beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42694] = { id = 42694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück von den Toten", description = "<Olothil seufzt.>\n\nMeine Schwester kann manchmal ganz schön meine Geduld strapazieren.\n\nAber egal... Ich habe ein paar Orte identifiziert, wo sich unsere Eltern aufhalten könnten. Ich werde zusammen mit Kallistia diese Gegend absuchen. Ihr habt uns schon so viel geholfen... Würdet Ihr uns noch einmal helfen und im Osten nach ihnen suchen?\n\nIhr könnt meine Seherkugel verwenden, um Euch die Orte anzuschauen, die unser Ritual offenbart hat.", sourceObjective = "Verwendet die Seherkugel, um zu sehen, wo sich die Nachtelfengeister aufhalten könnten, und zieht dann los, um sie zu retten.", progress = "Danke für Eure Hilfe, {class}.", completion = "Nach über zehntausend Jahren... Mutter und Vater wiederzusehen...\n\n<Dem Elfenmagier fehlen die Worte.>\n\nDanke, {name}. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42695] = { id = 42695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kayn Sonnenzorn", sourceObjective = "Es ist mir eine Ehre, {name}. Natürlich werde ich Euch als Champion und Stellvertreter dienen. Wie sollte es auch sonst sein?\n\nWir haben gerade erst begonnen, den Plan des Meisters umzusetzen, doch Ihr habt jetzt schon große Fortschritte erzielt. Wenn wir die Brennende Legion besiegen wollen, müssen wir wachsam bleiben. Jedes andere Ziel ist vergleichsweise bedeutungslos. Das Schicksal der Welt steht auf dem Spiel.\n\nAm Ende werden wir siegreich sein... Koste es, was es wolle!", sourceObjectiveStatus = "unverified-source-field" }
quests[42696] = { id = 42696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Dank Euch nimmt die Halle des Wächters langsam wieder ihre alte Form an.\n\nAber es gibt noch viel zu tun. Als <unser Anführer/unsere Anführerin> könnt Ihr über die zukünftige Entwicklung unseres Ordens bestimmen.\n\nSprecht mit Chronistin Elrianne. Sie wird Euch über alles unterrichten.", sourceObjective = "Sprecht mit Chronistin Elrianne.", completion = "Exzellente Arbeit, {name}! Ich sehe, dass die Halle des Wächters in guten Händen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[42697] = { id = 42697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Asha Rabenruf", sourceObjective = "Ihr möchtet mich als einen Eurer Champions?\n\n<Asha denkt einen Moment intensiv über Eure Bitte nach.>\n\nIch akzeptiere, habe aber eine Bedingung. Ich möchte, dass Ihr mich in den Feldeinsatz schickt. Hier auf der Teufelshammer kann ich zwar auch Nützliches leisten, doch auf Azeroth können meine Talente besser genutzt werden.\n\nDavon einmal abgesehen nehme ich an, dass der Plan nach wie vor daraus besteht, die Brennende Legion in die Knie zu zwingen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42698] = { id = 42698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selia, Master of Balefire" }
quests[42699] = { id = 42699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coura, Master of Arcana" }
quests[42700] = { id = 42700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quin'el, Master of Chillwind" }
quests[42701] = { id = 42701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Matronenmutter Malicia", sourceObjective = "Welch eine seltene Ehrerweisung. Zu den Illidari zu gehören, anstatt eine Dienerin zu sein. Ich sorgte mich zugegebenermaßen darum, dass Ihr mich womöglich nicht als Champion erwählen würdet.\n\nDoch jetzt habt Ihr genau das getan, und dafür könnte ich Euch küssen!\n\nEs leuchtete mir nie ein, warum man alle Welten im Feuer läutern sollte, wenn es doch so viele unterhaltsame Spielzeuge auf ihnen gibt. Sargeras ist bisweilen ein richtiger Spießer. Zusammen werden wir die Brennende Legion in die Knie zwingen, auf dass sie alle im Staub um ihr Leben betteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[42702] = { id = 42702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Millhaus Manasturm", sourceObjective = "Eure Halle hier ist gar nicht mal so übel, {name}. Hier gibt es bestimmt jede Menge netter Geheimnisse, die ich auftun kann. Ich glaube, hier bleib ich! Äh, natürlich nur, wenn Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42703] = { id = 42703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberhafte Technik", description = "Jetzt, da Ihr Eure ersten Champions habt, gibt es für die beiden jede Menge zu tun.\n\nErzmagierin Melis hat hart gearbeitet, um Eure Kommandozentrale einsatzbereit zu machen. Geht nach unten und bittet sie, Euch zu zeigen, was noch getan werden muss.", sourceObjective = "Sprecht mit Erzmagierin Melis.", completion = "Ich grüße Euch, {name}. Die Flammen Azeroths haben es uns ermöglicht, über unseren eigenen Horizont hinauszusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42704] = { id = 42704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Arkaner Zerstörer", sourceObjective = "<Der arkane Zerstörer gibt ein fragendes Fiepen von sich und sieht Euch erwartungsvoll an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42705] = { id = 42705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ravandwyr", sourceObjective = "Ich war viel zu lange Erzmagier Vargoths Lehrling. Womöglich ist es Zeit für mich, einem neuen Meister zu dienen. Ich wäre geehrt, wenn Ihr mich als Euren Champion annehmen würdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42706] = { id = 42706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Esara Verrinde", sourceObjective = "Wir beide waren zusammen schon recht erfolgreich. Gegen die Brennende Legion stehe ich Euch jederzeit gerne mit Schwertern und Zaubern zur Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42707] = { id = 42707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Ein magisches Gebrechen", description = "Der Verrat von Erzmagier Vargoth ist ein furchtbarer Verlust für unsere Sache, {name}. Wir werden uns um ihn kümmern müssen, aber zuerst ist Meryl an der Reihe. Sein Zustand hat sich verschlechtert.\n\nLeider ist es keine Krankheit, die ihn plagt, sondern ein magischer Angriff dämonischen Ursprungs. Womöglich steckt seine alte Nemesis dahinter, Kathra'natir. Wir müssen ihm etwas Zeit verschaffen.\n\nDas Auge Azsharas enthält eine gewaltige Menge arkaner Energie, die von Königin Azshara selbst stammt. Eine Phiole Wasser aus dem Körper von Azsharas Zorn würde ihm vorerst Linderung verschaffen.", sourceObjective = "Befüllt eine Phiole mit arkanem Wasser aus Azsharas Zorn.", progress = "Habt Ihr schon die Phiole mit arkanem Wasser?", completion = "Gut, Ihr seid gerade rechtzeitig zurück! Das wird Meryl am Leben halten, während wir seinen Angreifer suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42708] = { id = 42708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Bitte", description = "Falls Ihr einen Augenblick Zeit habt, <Todesgebieter/Todesgebieterin>... Ich würde gerne eine persönliche Angelegenheit mit Euch besprechen.\n\nVor einiger Zeit wurde ein Bruder der Schwarzen Klinge von der Dunklen Fürstin unter den Ruinen von Lordaeron eingekerkert.\n\nSylvanas hat sämtliche Verhandlungsversuche zu seiner Befreiung abgewehrt. Jetzt droht unserer Welt die Vernichtung. Für Diplomatie ist somit keine Zeit mehr.\n\nKoltira Todesweber kann nicht in Ketten gegen die Brennende Legion kämpfen.\n\nAlso werden wir sie zerschlagen.", sourceObjective = "Rettet Koltira Todesweber aus Unterstadt.", progress = "Die Zeit ist gekommen, Koltira Todesweber aus seiner Gefangenschaft zu befreien.", completion = "Sylvanas wird über unsere Taten nicht erfreut sein, doch wir haben jetzt dringendere Sorgen als das Gemüt der Dunklen Fürstin.", sourceObjectiveStatus = "unverified-source-field" }
quests[42711] = { id = 42711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ewigen Magier" }
quests[42712] = { id = 42712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Verzwickte Lage" }
quests[42713] = { id = 42713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Schneckentempo" }
quests[42714] = { id = 42714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Mythana" }
quests[42715] = { id = 42715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost DK - Highmountain Event" }
quests[42716] = { id = 42716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost DK - Val'sharah Event" }
quests[42717] = { id = 42717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost DK - Stormheim Event" }
quests[42718] = { id = 42718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost DK - Azsuna Event" }
quests[42719] = { id = 42719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Säuberung des Traumpfads", description = "Funkelchen hat viele Freunde. Ich mag Freunde!\n\nAber wisst Ihr, wer nicht zu Funkelchens Freunden gehört? Schreckliche Monster aus dem Alptraum!\n\nDie tun Funkelchens Verbündeten weh und machen den Hain ganz eklig!\n\nHier muss unbedingt sauber gemacht werden, aber mir ist die Magie ausgegangen.\n\nKönnt Ihr Funkelchen helfen und etwas geläutertes Wasser bringen? Ihr müsst ganz, ganz weit weg... zum Auge Azsharas, wo die Naga leben.", sourceObjective = "Sammelt 25 Einheiten verfeinertes Wasser von den Naga im Auge Azsharas und besiegt Azsharas Zorn.", progress = "Arme, arme Blumen...", completion = "Oh! Reines Wasser, so klar und magisch! Vielen Dank, Held!", sourceObjectiveStatus = "unverified-source-field" }
quests[42722] = { id = 42722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in Käfigen", description = "<Korine stampft mit dem Fuß auf und bewegt sich kein Stück.>\n\nSie haben meine Freunde in Käfige gesperrt!\n\nSorgt dafür, dass diese bösen Männer ihnen nicht mehr wehtun! Sie holen sie aus dem Garten und sie kommen nicht zurück!\n\n<Korine deutet stur zur Tür hinüber.>\n\nIch gehe erst nach Hause, wenn sie wieder da sind!", sourceObjective = "Befreit 3 Bürger der Nachtgeborenen aus der Gefangenschaft.", progress = "Habt Ihr sie rausgelassen?", completion = "Ihr habt sie befreit? Da bin ich aber froh. Ich mochte es auch nicht, im Käfig zu stecken...", sourceObjectiveStatus = "unverified-source-field" }
quests[42723] = { id = 42723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Harte Schale, weicher Kern" }
quests[42724] = { id = 42724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42725] = { id = 42725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Reichtum teilen", description = "In letzter Zeit gab es viele verstörende Änderungen bezüglich unserer wertvollsten Ressource, des Arkweins.\n\nIch gehe davon aus, dass Thalyssra Euch darüber aufgeklärt hat, was passiert, wenn ein Nachtgeborener keinen Zugang zu einer Machtquelle wie dem Arkwein erhält.\n\nSeitdem die Dämonen da sind, gab es Rationierungen. Viele erhalten nicht mehr genug, um sich ausreichend zu nähren.\n\nSchafft mir so viel Arkwein herbei, wie Ihr nur könnt. Ich werde ihn dann den richtigen Leuten zukommen lassen.", sourceObjective = "Sammelt 20 Flaschen Arkwein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42726] = { id = 42726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Gladiator's Battlegear" }
quests[42727] = { id = 42727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transition to Forge Quests" }
quests[42728] = { id = 42728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mlrglrmg für Grlmrgl", description = "Mrglm, rmgrlg mrlgmrl.\n\nGrmrglmrl mlrmglrgr mlrmlgr! Rglrmgl rmglrgmlr mlmlglr mglgrgrlm, grlgmr, mlgr, lrgmlrgr rmgrmlg mlrg! Mlrgr?\n\nMrlgmrlgmrl rmglrmglr!\n\n<Perlenjäger Phin deutet eine stechende Bewegung an.>" }
quests[42729] = { id = 42729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenger's Armaments" }
quests[42730] = { id = 42730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfoggers zumutbare Anfrage", description = "Ach, was erlaubt sich der kleine grüne Giftzwerg eigentlich? Marin Noggenfogger erpresst uns. Wenn wir seine \"preislich absolut zumutbare Materialanfrage\" nicht erfüllen, verweigert er den weiteren Zugang zum Tiegel.\n\nMarin verlangt enorme Mengen Aethril. Er meinte, Ihr hättet ihm kürzlich ein Messer an die Kehle gehalten und er revanchiert sich jetzt einfach.\n\nNatürlich kann ich ihn auch einfach unschädlich machen, wenn Euch das lieber wäre.", sourceObjective = "Sammelt 20 Aethril.", progress = "Heda {name}, habt Ihr die Reagenzien, um die ich Euch gebeten hatte? Eine Hand wäscht die andere... oder bezahlt zumindest jemanden dafür.", completion = "Wir tragen uns nichts nach, ja? Geschäft ist Geschäft, und das Geschäft brummt. Ich habe eine Gelegenheit gewittert und wahrgenommen. Genau wie Ihr.\n\nAls Zeichen meiner Verbundenheit zu Eurer kleinen Organisation und als Geste guten Willens habt Ihr hier eine Probe des Produkts. Zauberhaft. Prost!", sourceObjectiveStatus = "unverified-source-field" }
quests[42731] = { id = 42731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Wächterinnen", description = "So wenig es uns auch gefallen mag, aber wir brauchen die Hilfe der Wächterinnen, wenn wir den Sargeritschlüsselstein finden wollen. Sie haben ihn Euch abgenommen, als wir alle im Verlies gefangen waren.\n\nDa Maiev vermisst wird, ist Sira Mondhüter momentan ihre Anführerin. Ich habe in Eurem Namen zugestimmt, dass wir ihnen dabei helfen werden, einige der mächtigeren Kreaturen aufzuspüren, die aus dem Verlies der Wächterinnen entkommen sind. Im Gegenzug wird sie uns zeigen, wo wir den Schlüsselstein finden können.", sourceObjective = "Benutzt die Späherkarte und schließt die Missionen der Reihe \"Helft den Wächterinnen\" ab.", completion = "Nun, wir haben alles getan, was sie verlangt hat, aber das hat Sira Mondhüter nicht gereicht.\n\nSie will noch eine Sache... und Ihr sollt sie höchstpersönlich erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42732] = { id = 42732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödlichere Kriegsgleven", description = "Loramus hat eine Methode erforscht, wie man unsere Kriegsgleven noch tödlicher machen kann, insbesondere gegen Dämonen.\n\nWenn man ihm trauen darf, dann braucht er dafür nur eine gewisse Menge Obliterum. Diese Substanz wird eigentlich zur Verstärkung von Rüstungen verwendet, aber Loramus besteht darauf, dass er sie für unsere Kriegsgleven verwenden kann.\n\nWir alle werden sicherlich davon profitieren, wenn die Kriegsgleven auf dem Schlachtfeld noch tödlicher sind.", sourceObjective = "Sammelt 1 Obliterum, das Ihr in der Schmiede des Schicksals auf dem Handelsmarkt der Magier in Dalaran oder im Auktionshaus erhaltet.", progress = "Habt Ihr das Obliterum beschafft?", completion = "Das Zeug ist schwer zu finden und teuer. Beeindruckend! Ich kann es kaum erwarten, die Ergebnisse zu sehen.\n\nBereit für die nächste große Aufgabe? Das Böse darf nicht zur Ruhe kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42733] = { id = 42733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderer Treibstoff", description = "Alle Konstrukte der Legion, einschließlich der Teufelshammer, werden von Seelen angetrieben. Wenn wir die Kommandozentrale nach Niskara verlegen wollen, werden wir einige ziemlich mächtige Seelen brauchen!\n\nIhr seid doch kreativ, {name}. Ich bin sicher, dass Ihr einen Weg finden werdet, das von uns Benötigte von den richtigen Kreaturen zu beschaffen.", sourceObjective = "Sammelt 15 stattliche Seelen von Dungeonbossen in Legion.", progress = "{name}, habt Ihr das beschafft, was Allari von Euch als Treibstoff erbeten hatte?", completion = "Natürlich. Wie alle Konstrukte der Legion wird auch die Teufelshammer von Seelen angetrieben. Ihr habt einige der mächtigsten Seelen gesammelt, die es gibt.\n\nSie sollten ausreichen, uns an jeden von Euch gewünschten Ort zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42734] = { id = 42734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in das Oculus", description = "Ich befürchte, dass Kathra'natir hinter dem Angriff auf Meryl steckt. Uns bleibt nur sehr wenig Zeit, um etwas zu unternehmen.\n\nErzmagier Vargoths Beteiligung halte ich nicht für Zufall. Es grämt mich zwar sehr, einen Erzmagier seiner Statur zu vernichten, den ich vor allem einst meinen Freund nannte. Doch diesen Verrat können wir nicht ungestraft lassen.\n\nEs ist an der Zeit, ihm in das Oculus zu folgen.", sourceObjective = "Sprecht mit Erzmagier Khadgar, sobald Ihr bereit für die Reise zum Oculus seid.", completion = "Ihr habt das Unvorstellbare geschafft, {name}. Wir stehen alle in Eurer Schuld. Mit Stolz werde ich Euch ab jetzt als Erzmagier {name} ansprechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42735] = { id = 42735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malace im Vrykulland", description = "Ich habe mich etwas in Sturmheim umgesehen. Dabei habe ich entdeckt, dass die Wellenskorn ein Vrykulstamm sind, dem die eigenen Kvaldirbrüder den Weg zum Meer abgeschnitten haben. Viele der Wellenskorn stehen in Diensten der Legion und sind nun Teufelsskorn geworden.\n\nMalace Schatten wurde zuletzt gesehen, als sie auf die Kriegsbasis der Teufelsskorn zueilte. Es ist nicht unwahrscheinlich, dass sie gefangen genommen wurde.\n\nIch habe einen Flug nach Sturmheim für Euch arrangiert. Wenn Ihr bereit seid, könnt Ihr durch das Tor nach Dalaran reisen und dort mit Aludane Wolkenweiß an Krasus' Landeplatz sprechen.", sourceObjective = "Nehmt einen Flug von Aludane Wolkenweiß und findet Malace Schatten in Sturmheim.", completion = "{name}, seid Ihr das? Eine seltsame Wendung der Dinge, meint Ihr nicht auch?\n\nIhr seid frei und jetzt bin ich die Gefangene.", sourceObjectiveStatus = "unverified-source-field" }
quests[42736] = { id = 42736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenruinierung", description = "Ein Käfig konnte mich nicht aufhalten, also haben die Vrykul diese Runensteine verzaubert, um mich hier gefangen zu halten. Jeder erhält seine Energie von einer anderen Teufelsskornrune.\n\nLeider haben sie diese Runen unterschiedlichen Hütern gegeben, die sich in ganz Sturmheim verstreut aufhalten.\n\nWenn Sira also gemeint hat, dass Ihr Euren kostbaren Schlüsselstein zurückbekommen könnt, dann müsst Ihr mich erst hier herausholen.\n\nDann sehen wir weiter.", sourceObjective = "Deaktiviert die drei Runensteine, um Malace zu befreien.", completion = "Ich habe Euch wohl unterschätzt. Gut. Ich lerne gern Neues dazu.\n\nMöchtet Ihr mir bei einer letzten kleinen Sache aushelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42737] = { id = 42737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenruinierung: Runenskeld Rollo", description = "<Besorgt die Rune von Runenskeld Rollo, um seinen Runenstein zu deaktivieren.>", sourceObjective = "Besorgt Rollos Rune.", progress = "<Der Runenstein brummt vor teufelsverderbter Macht. Deaktiviert ihn mit seiner zugehörigen Rune.>", completion = "<Der Runenstein beginnt zu vibrieren, als Ihr mit der Rune in der Hand näher kommt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42738] = { id = 42738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenruinierung: Runenfürst Ragnar", description = "<Besorgt die Rune von Runenfürst Ragnar, um diesen Runenstein zu deaktivieren. Falls Ihr noch keinen Greifhakenwerfer habt, besorgt ihn Euch, um die Mauern von Hrydshal zu erklimmen.>", sourceObjective = "Besorgt Ragnars Rune.", progress = "<Der Runenstein hält Malace Schatten gefangen. Verwendet Ragnars Rune, um ihn zu deaktivieren.>", completion = "<Ragnars Rune wird warm, als Ihr Euch dem Runenstein nähert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42739] = { id = 42739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenruinierung: Runengelehrter Floki", description = "<Dieser Runenstein hält Malace Schatten gefangen. Er kann nur mithilfe der Rune des Runengelehrten Floki zerstört werden.>", sourceObjective = "Besorgt Flokis Rune.", progress = "<Wer weiß, wie lange die Teufelsskornvrykul Malace Schatten noch am Leben lassen werden? Ihr solltet Euch lieber früher als später um den Runenstein kümmern.>", completion = "<Die Rune und der Runenstein beginnen, mit wachsender Macht zu leuchten und zu summen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42740] = { id = 42740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Verheerte Küste", description = "Das ist Euer Schiff, {name}. Es ist ein feines Schiff, das schon viele Schlachten gesehen hat. Sprecht mit dem Kapitän, wenn Ihr bereit seid aufzubrechen.\n\nViel Glück da draußen. Wir haben nur wenige Berichte über die Vorgänge an der Verheerten Küste erhalten, aber ich bin mir sicher, dass König Varian alles unter Kontrolle hat.", sourceObjective = "Reist mit dem Schiff der Dritten Flotte an die Verheerte Küste.", completion = "Ah, {name}, Ihr seid auf den Beinen! Ich bin erleichtert, dass Ihr dieses Blutbad überlebt habt. Wir haben dort unten so viele gute Männer und Frauen verloren...\n\n\n\nVerdammt soll die Horde sein, dass sie uns der Legion wie auf einem Silbertablett serviert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[42741] = { id = 42741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Expansion Started Tracking Quest" }
quests[42742] = { id = 42742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Zornfäule" }
quests[42743] = { id = 42743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Kudzilla" }
quests[42744] = { id = 42744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Bewahrung der Bewahrer" }
quests[42745] = { id = 42745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Bärendienst" }
quests[42746] = { id = 42746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Abgewrackt" }
quests[42747] = { id = 42747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Wildekin wohnen", description = "Oft haben Eulenbestien den Auftrag, jene Orte zu beschützen, die für Elune von Bedeutung sind. Doch wenn Elunes Einfluss nachlässt oder abreißt, können die Kreaturen wirklich gefährlich werden.\n\nLeider müssen diese Wildekin beseitigt werden. Die jüngsten Störungen in Val'sharah haben die Kreaturen in den Wahnsinn getrieben.\n\nSobald sie einmal verloren sind, bleibt nur eine Lösung.\n\nIch bringe es nicht übers Herz, Elunes Schöpfungen zu töten, doch ich weiß, es muss getan werden.", sourceObjective = "Tötet 10 Eulenbestien und 8 wogende Knochenschleime innerhalb der Schummerlichtgrotte.", completion = "Ich wünschte wahrlich, dass dies nicht nötig wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[42748] = { id = 42748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgrüne Schwestern", description = "Die Eulenbestien hier scheinen sich von Elune losgesagt zu haben.\n\nEin Kontingent Dryaden ist in ihr Gebiet gezogen, um dem Problem auf den Grund zu gehen. Aber es ist keine von ihnen zurückgekehrt.\n\nIch befürchte das Schlimmste und gehe davon aus, dass sie gerettet werden müssen.\n\nWährend ich versuche herauszufinden, ob es noch Hoffnung für die Eulkin gibt, möchte ich Euch bitten, alle Schwestern zu befreien, die Ihr in der Grotte finden könnt.", sourceObjective = "Rettet 6 Schwestern des Mondes in der Schummerlichtgrotte.", completion = "Die Eulenbestien tun WAS?! Sie schmelzen die Dryaden ein und verwenden ihre Knochen, um Diener zu erschaffen?! Aber... Aber wie ist das überhaupt möglich?", sourceObjectiveStatus = "unverified-source-field" }
quests[42749] = { id = 42749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Gespann", description = "Ich kam hierher, um einen Teufelslord namens Lochaber gefangen zu nehmen oder zu töten. Und nach Gefangenen steht mir nicht mehr der Sinn.\n\nIch werde mir meine Waffe nehmen und mich auf den Weg zur Brücke vor der Pforte der Tapferkeit machen. Dort herrscht ein schreckliches Chaos voller Teufelsskornvrykul und Dämonen.\n\nWas denkt Ihr denn, wie ich erwischt wurde?\n\nIch würde also lieber nicht wieder dort hineingehen. Ich glaube aber, ich weiß, wie wir den Dämon dazu kriegen, zu uns herauszukommen.", sourceObjective = "Trefft Euch mit Malace Schatten auf der Brücke zur Pforte der Tapferkeit und tötet dann Lochaber.", sourceObjectiveStatus = "unverified-source-field" }
quests[42750] = { id = 42750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumfänger", description = "Ich werde nicht viel länger durchhalten...\n\nIch habe einen Traumfänger mitgebracht, mit dem ich den Totems der Eulenbestien die Magie entziehen sollte.\n\nDas ist die einzige Möglichkeit, die Barriere zu überwinden, hinter der Bewahrer Remulos gefangen gehalten wird.\n\nBitte bringt zu Ende, was mir nicht gelungen ist.", sourceObjective = "Ladet den Traumfänger mithilfe der Totems der Eulenbestien in der Schummerlichtgrotte auf.", completion = "Ich kannte Leirana... Sie hatte ein ganz besonders mitfühlendes Wesen und war eine von Remulos' Lieblingen. Wenn ihre Annahme, dass er gefangen wurde, stimmt, haben wir keine Zeit, ihren Tod zu betrauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[42751] = { id = 42751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondhäscher", description = "Wir dürfen nicht zu spät kommen! Wenn Bewahrer Remulos in Gefahr ist, muss er beschützt werden.\n\nMithilfe des Traumfängers sollten wir in der Lage sein, in das Nest der Eulenbestie Knochenfluxus einzudringen.\n\nWir müssen sie vernichten, um Bewahrer Remulos freizubekommen!", sourceObjective = "Besiegt Knochenfluxus und rettet Bewahrer Remulos in der Tiefenschlucht.", completion = "Ich habe schwere Wunden erlitten und meine Magie ist fast aufgebraucht. Ich muss mich von dieser Schwächung erholen und in den Hain der Träume zurückkehren.\n\nDie Eulkin hier können von sterblicher Hand nicht gerettet werden, aber vielleicht wird Elune eines Tages wieder ihr Licht auf sie scheinen lassen.\n\nIch danke Euch, {name}. Mögen Eure Wege gesegnet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42752] = { id = 42752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Einbruch in das Verlies", description = "<Nun müsst Ihr nur noch zur Insel der Behüter vor der südwestlichen Küste Azsunas reisen. Dort müsst Ihr in das Verlies der Wächterinnen einbrechen und in seine tiefsten Winkel vordringen, wo Ihr einst gefangen gehalten wurdet.>\n\n<Im sogenannten Kerker des Verräters, wo die Wächterinnen einst Illidans Leichnam aufbewahrten, werdet Ihr den Sargeritschlüsselstein finden.>", sourceObjective = "Bergt den Sargeritschlüsselstein.", progress = "Wart Ihr erfolgreich, {name}? Konntet Ihr den Sargeritschlüsselstein bergen?", completion = "Endlich haben wir an Cordana Teufelsang für die ganzen {class} Rache geübt, die sie dazu verführt hat, Angehörige des Dämonenpakts zu werden. Cyana, Tirathon, Glayvianna, Cailyn, Illysanna und all die anderen.\n\nIhr Tod war schon lange überfällig.\n\nDer Sargeritschlüsselstein ist wieder in unserem Besitz. Jetzt können wir unseren Blick in die Zukunft richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42753] = { id = 42753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Einbruch in das Verlies", description = "Die Wächterinnen haben die Abmachung erfüllt. Wir müssen nur noch zur Insel der Behüter vor der südwestlichen Küste Azsunas reisen. Dort müsst Ihr in das Verlies der Wächterinnen einbrechen und in seine tiefsten Winkel vordringen, wo wir einst gefangen gehalten wurden.\n\nIm sogenannten Kerker des Verräters, wo die Wächterinnen früher den Leichnam des Meisters aufbewahrten, werdet Ihr den Sargeritschlüsselstein finden.\n\nViel Glück, {name}.", sourceObjective = "Bergt den Sargeritschlüsselstein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42754] = { id = 42754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Sprünge", description = "Es stimmt zwar, dass die Teufelshammer über Energie verfügt, doch ihr Sprungantrieb funktioniert leider nicht. Wenn wir eine Dämonenwelt angreifen wollen, muss die Kommandozentrale zu Sprüngen fähig sein.\n\nWir brauchen einige Ersatzteile.\n\nZu unserem Glück hat die Legion einige Befehlszentren und Seelenmaschinen auf die Verheerten Inseln mitgebracht. Ihr findet sie in Faronaar in Azsuna sowie in der Teufelsseelenbastion in Suramar.", sourceObjective = "Sammelt eine Teufelsmotoreinspritzdüse, eine Seelenkonfigurationsmatrix, eine Teufelsmotorzündung und einen Umwandler für widerwärtige Geister.", progress = "Die Funktionsweise ist widerlich. Das ganze Ding wird von Seelen angetrieben... Ihr wollt absolut NICHT wissen, was mit denen geschieht.", completion = "Diese Teile sollten ihren Zweck erfüllen. Etwas Besseres hätten wir uns nicht wünschen können.\n\nAber sagt mir: Waren die Dämonen wütend, als Ihr ihnen ihre wertvollen Komponenten entwendet habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[42755] = { id = 42755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Azsunianische Perlen" }
quests[42756] = { id = 42756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Hungers", description = "Ich bin schwach. Der Hunger zehrt mich auf. Ich verstehe jetzt, warum Euer Drache in diesem Teich liegt.\n\n<hust, hust>\n\nIch bin gekommen, um Euch zu warnen, aber... es scheint zu spät zu sein.\n\nIch kann ihn da draußen hören. Ael'Yith... ist... hier...", sourceObjective = "Tötet Ael'Yith und sein Konstrukt.", completion = "Hah! Ha ha ha haaaa!\n\nSo lebendig habe ich mich schon seit JAHREN nicht mehr gefühlt!\n\n{name}, Ihr habt nicht nur meinen Manateich wieder aufgefüllt, sondern auch meine Brut gerettet. Das werden wir niemals vergessen. Die Blauen von Azsuna stehen tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[42757] = { id = 42757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Bedrohung der See" }
quests[42758] = { id = 42758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr werdet ein größeres Boot brauchen!", description = "Haie. Sie sind die größte Bedrohung für uns Piraten. Also... nach Skorbut, Ninjas und der Rechtsordnung. Zum Glück haben wir es heute nur mit den Haien zu tun.\n\nGeht los und zieht ihnen ein paar Zähne. Ich brauche eine neue Halskette.", sourceObjective = "Zieht 33 rasiermesserscharfe Haifischzähne.", progress = "Ich benötige dreiunddreißig rasiermesserscharfe Haifischzähne. Und nicht einen weniger!", completion = "Oha! Da klebt ja noch Blut dran! Dann scheint er Euch ja einen ordentlichen Biss verpasst zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[42762] = { id = 42762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gefährte des Wanderers", description = "Fu Zan... eine weise Wahl. Wenn die Legenden wahr sind, werden Euch seine Kräfte in unserer Sache gute Dienste leisten.\n\nWir glauben, dass es sich bei dem Stab des Affenkönigs um den legendären Fu Zan handeln könnte. Aber seit mehr als einem Jahr hat ihn niemand mehr mit der Waffe gesehen.\n\nZuletzt war der Affenkönig im Tiankloster zu finden. Macht Euch auf alles gefasst! Er ist für seine... eigenwilligen Antworten berüchtigt.\n\nWestlich des Tempels findet Ihr Tak-Tak, einen Drachenmeister der Ho-zen. Ihr müsst unverzüglich mit ihm sprechen.", sourceObjective = "Sprecht mit Tak-Tak, um zum Tiankloster zu fliegen und Euch mit dem Affenkönig zu treffen.", completion = "Ihr sucht meinen Stab? Da lach ich mich schlapp!\nHilfe und Zeit wollt Ihr, und beides ist mein?\nNun gut, Nappel, dann lauscht diesem Reim:\n\nDrei neue Rätsel ich für Euch habe,\ndrei richtige Antworten sind Eure Gabe.\nHabt Ihr den Geist und seid Ihr es wert?\nAntwortet dem König oder macht sofort kehrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[42763] = { id = 42763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran Hidden Demon 01" }
quests[42764] = { id = 42764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Der Geist in der Maschine" }
quests[42765] = { id = 42765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung im Tempel", description = "Stark war mein Stab und seine Macht ohnegleichen, aber ich war nicht sein Meister und so musste er weichen.\n\nEin Geschenk von Yu'lon war er, nur für eine Aufgabe bestimmt. Als mein Werk war getan, sie ihn sich holte geschwind.\n\nYu'lon hütet den Stab für den Nächsten, den sie auserwählt. Zu ihr wir jetzt gehen, um zu sagen, was Euch quält.", sourceObjective = "Begleitet den Affenkönig zum Tempel der Jadeschlange und beschafft Fu Zan, den Gefährten des Wanderers.", completion = "Ich wusste, Ihr würdet es schaffen, {name}. Es ist mir eine Ehre, Euch zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42766] = { id = 42766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel des Fasses", description = "Meine Waffe ist toll, besonders in Schlachten.\nUnd plagt Euch der Hunger, auch nicht zu verachten.\n\nMeine Lieblingsflasche hängt daran, befestigt mit einer Schnur.\nDas Gebräu darin ist das weltbeste, so lautet mein Schwur.\n\nWollt Ihr meine Waffe, bringt mir etwas für meinen Bauch.\nEtwas mit starkem Aroma, bloß kein Gesöff mit sanftem Hauch.", sourceObjective = "Sucht nach den Objekten, die der Affenkönig in seinem Rätsel umschreibt.", progress = "Ah, schon wieder da. Hat der Nappel gefunden, wonach ich suche?", completion = "Die Grünlinge hätten nur zu gern an diesem müffelnden Gebräu geleckt. Es ist stark und es müffelt sehr, aber ob es auch schmeckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[42767] = { id = 42767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel des Landes", description = "Meine Waffe ist stark, doch im Angriff hilft sie nicht viel.\nZu beschützen die Schwachen, das ist ihr Ziel.\n\nIm Tal bestellen sie die Felder bis spät in die Nacht,\ndie Früchte ihrer Arbeit gehören zu mir gebracht.\n\nSäcke voll Korn sind, was ich begehre,\ndoch nur vom Feuer geküsstes Korn gereicht Euch zur Ehre.\n\nBringt mir, wonach ich verlange.", sourceObjective = "Sucht nach den Objekten, die der Affenkönig in seinem Rätsel umschreibt.", progress = "Ah, schon wieder da. Hat der Nappel gefunden, wonach ich suche?", completion = "Die Nappel mussten für dieses Korn hart rackern. Um nicht zu hungern, müssen sie den lieben langen Tag das Feld beackern.\n\nDa diese Säcke jetzt vor den Grünlingen sicher sind, sollten wir sie ihnen zurückgeben.\n\nNa gut, vielleicht behalten wir einen Sack für uns. Wir müssen ja auch leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42768] = { id = 42768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel der Reinheit", description = "Meine Waffe wollt Ihr in den Händen spüren? Dann solltet Ihr Euch dies hier zu Gemüte führen:\n\n  \"Etwas Weiches ich suche, doch hart zugleich.\n\n   Notwendig es ist für Arm und Reich.\n\n   Der Ursprung des Lebens, und doch bringt es den Tod:\n\n   Es ist die Geißel der Küste und die Rettung in der Not.\n\n   Überall man es findet, doch was zählt ist allein:\n\n   Das, was ich suche, stammt aus einer Quelle ganz rein.\"\n\nAlso bringt mir, was ich begehre.", sourceObjective = "Sucht nach dem Objekt, das der Affenkönig in seinem Rätsel umschreibt.", progress = "Ah, schon wieder da. Hat der Nappel gefunden, wonach ich suche?", completion = "Viel mehr Wasser in diesem spritzigen Geisterkern, als man denken mag. Genug für eine riesige Schüssel oder ein kleines Bad!\n\nIch wette, der ein oder andere Zweck ist ihm angemessen. Wir könnten ihn für eine verfiddelt gute Brapsche auspressen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42769] = { id = 42769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Bringt mir die Augen" }
quests[42770] = { id = 42770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Führung", description = "Hochlord Tirion mag nicht mehr unter uns weilen, doch der Aschenbringer ist noch irgendwo da draußen. Seine Macht würde die Legion zerschmettern. Wir müssen ihn finden!\n\nIch wünschte, es wäre so leicht, ihn dort zu suchen, wo Tirion gefallen ist. Aber er könnte mittlerweile überall in dieser infernalischen Landschaft verborgen sein.\n\nEs gibt einen alten Freund, der uns helfen könnte, die Klinge zu finden. Ich bitte Euch, mir zu vertrauen und mich zu Uthers Grabmal in den Pestländern zu begleiten. Dort werden wir Antworten finden.", sourceObjective = "Trefft Euch mit Lord Maxwell Tyrosus bei Uthers Grabmal in den Westlichen Pestländern.", completion = "Diese tapferen Beobachter benötigen unsere Hilfe. Wenn wir unseren eigenen Leuten nicht helfen, wird das Licht auch nicht unsere Gebete erhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[42771] = { id = 42771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden wahren", description = "Die Störungen des Lichts haben verlorene Seelen in das Reich der Lebenden gezogen, die nun über den Friedhof wandeln. Aber in Wahrheit suchen sie nur Trost... wie wir alle in diesen finsteren Zeiten, seitdem Hochlord Tirion verschieden ist.\n\nAber dennoch bedrohen sie den Frieden des Grabmals, das wir zu schützen gelobt haben. Wenn wir diesen Frieden wiederherstellen wollen, müssen sie gebannt werden.", sourceObjective = "Exorziert 9 Geister.", progress = "Wir sind Euch für Eure Hilfe sehr dankbar.", completion = "Endlich haben die armen Seelen Frieden gefunden. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42772] = { id = 42772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiliger Boden", description = "Wir müssen dafür sorgen, dass die Ruhe aller, die hier begraben sind, nie mehr gestört wird. Allein die Anwesenheit ihrer Geister trübt das Licht.\n\nSo kann es nicht weitergehen.\n\nIch muss diese Barriere aufrechterhalten, damit keine der verlorenen Seelen in die Ruhestatt des Lichtbringers eindringt. Wenn Ihr die Gräber läutert, hat dieser Wahnsinn endlich ein Ende.", sourceObjective = "Läutert die Gräber am Trauerhügel.", completion = "Gut. Mit der Zeit werden auch die letzten verbleibenden Seelen ihren Weg nach Hause finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42773] = { id = 42773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht offenbart", description = "Wir ersuchen nicht einen lebenden Freund um Hilfe, sondern einen vor langer Zeit verstorbenen.\n\nUther der Lichtbringer war ein Meister des Lichts und geschickter als jeder andere Paladin. Wenn wir ihn erreichen, kann er uns vielleicht helfen, den Aschenbringer zu finden.\n\nFür die Zeremonie ist alles vorbereitet. Geht zum Grabmal, wenn Ihr bereit seid.", sourceObjective = "Haltet Zwiesprache mit Uther dem Lichtbringer.", progress = "Wir müssen tun, was notwendig ist.", completion = "Tirion... Ist das möglich?", sourceObjectiveStatus = "unverified-source-field" }
quests[42774] = { id = 42774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung siegt", description = "Tirion ist... noch am Leben! Wir müssen ihn retten.\n\nDie Kapelle des Hoffnungsvollen Lichts ist ganz in der Nähe. Wir müssen unsere Truppen sammeln und sofort zur Verheerten Küste aufbrechen.", sourceObjective = "Trefft Euch mit Lord Maxwell Tyrosus an der Kapelle des Hoffnungsvollen Lichts.\n\nBereitgestellter Gegenstand:", completion = "Wir sind zur Abreise bereit, wenn Ihr es auch seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[42775] = { id = 42775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krux des Plans", description = "Wir haben Akama. Cordana Teufelsang wurde ausgeschaltet. Und jetzt haben wir auch den Sargeritschlüsselstein.\n\nAllmählich fügen sich die Mosaiksteine zu einem Ganzen.\n\nIch überlasse Euch die Ehre, {name}.", sourceObjective = "Platziert den Sargeritschlüsselstein über der Späherkarte.", progress = "Jetzt befinden sich alle Dämonenwelten in unserer Reichweite.", completion = "Nachdem wir den Sargeritschlüsselstein jetzt in der Hand haben, müssen wir nur noch unsere Streitkräfte aufstellen und einen Invasionsplan vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42776] = { id = 42776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Würdige", description = "Während unsere Streitkräfte und unser Einfluss immer weiter anwachsen, werdet Ihr vertrauenswürdige Begleiter brauchen, denen Ihr die wichtigsten Missionen anvertrauen könnt.\n\nDie Zeit ist jetzt gekommen, zwei Würdige in die Reihen Eurer Champions aufzunehmen.\n\nMeiner Ansicht nach solltet Ihr in Erwägung ziehen, Belath und Malicia zu rekrutieren. Beide haben sich als unverzichtbar erwiesen.", sourceObjective = "Rekrutiert Belath Dämmerklinge und Matronenmutter Malicia als Eure Champions.", completion = "Es stehen nun sechs Champions, alle Illidari und ihre Streitkräfte sowie eine wachsende Anzahl Truppen unter Eurem Befehl. Sie alle sind bereit, sich zu opfern, um die Brennende Legion in die Knie zu zwingen.\n\nZeit, uns auf die entscheidende Phase vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42777] = { id = 42777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Belath Dämmerklinge", sourceObjective = "Ihr erwählt mich als einen Eurer Champions?\n\n<Belath wirkt überrascht und erfreut.>\n\nDas ist eine große Auszeichnung. Ich schwöre Euch erneut meinen treuen Dienst, {name}. Ich mache es zu meiner Aufgabe, die Feinde der Illidari in Eurem Namen zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42778] = { id = 42778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Crusader" }
