quests[42780] = { id = 42780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Aus dem Schlund der Hölle" }
quests[42781] = { id = 42781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Entwaffnung der Wache" }
quests[42782] = { id = 42782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allzeit bereit", description = "Es sind Verbündete aus ganz Azeroth nach Sturmwind gekommen, um uns im Kampf gegen die Brennende Legion beizustehen.\n\nBevor Ihr loszieht, solltet Ihr sie aufsuchen. Jedes kleinste Detail der Vorbereitung ist hilfreich!", sourceObjective = "Sucht die Allianztruppen im Hafen von Sturmwind auf.", completion = "Gut, dass Ihr Euch gründlich vorbereitet habt. Man weiß wirklich nie, was einen da draußen erwartet.\n\nWir haben diese Ringe für hochrangige Mitglieder der Allianz anfertigen lassen. Möge er Euch in den kommenden Schlachten beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42783] = { id = 42783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Blüten der Nacht" }
quests[42784] = { id = 42784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Die hinterlistige Schülerin" }
quests[42785] = { id = 42785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Höhlenmutter Ylva" }
quests[42786] = { id = 42786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Groteske Überreste", description = "Diese grotesken Überreste sind eine Verschmelzung aus dickem Schleim und Knochen, die von Dryaden zu stammen scheinen.\n\nGuviena Klingenlied hätte großes Interesse, dies zu sehen.", sourceObjective = "Sprecht mit Guviena Klingenlied an den Flüsternden Felsen.\n\nBereitgestellter Gegenstand:", completion = "Diese Überreste... wie schrecklich! Sie machen Dryaden zu willenlosen Schleimhaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42787] = { id = 42787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefsache", description = "Meiner Ansicht nach sind uns die Wächterinnen etwas schuldig für all die Jahre, die wir eingekerkert waren. Ihre neue Anführerin Sira Mondhüter teilt diese Auffassung aber leider nicht.\n\nObwohl Eure Champions bereits mehrere ihrer gesuchten Ausbrecher erledigt haben, reicht ihr das noch nicht. Sie verlangt doch tatsächlich, dass Ihr Euch als Geste des Vertrauens selbst um die folgenden Aufgaben kümmert.\n\nIhr werdet die Koboldkerzen auslöschen müssen, um die verschlingende Finsternis zu beschwören. Die anderen zwei sollten deutlich unkomplizierter sein.", sourceObjective = "Tötet die verschlingende Finsternis am Hochberg, Hertha Grimmdottir in Suramar und Theryssia in Val'sharah.", completion = "Die Wächterinnen hätten schon viel früher mit uns zusammenarbeiten sollen. Dennoch wissen wir jetzt, dass wir in Sturmheim nach der Wächterin Malace Schatten suchen müssen. Ihr wurde die Aufbewahrung des Sargeritschlüsselsteins anvertraut.\n\nIch selbst habe auch ein paar Informationen ausgekundschaftet. In Kombination sollte dieses Wissen Euch die richtige Richtung weisen.\n\nSchon bald wird der Schlüsselstein unser sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42788] = { id = 42788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Die Rückkehr der Bestie" }
quests[42792] = { id = 42792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen setzen", description = "Während Ihr da draußen wart, habe ich mich umgehört.\n\nIhr sucht nach Aufseher Durant. Er wohnt in der Nähe des Schimmerlichtgartens.\n\nIch kann Euch helfen, an ihn ranzukommen, aber Ihr werdet Hilfe brauchen. Es gibt drei Personen, die über die notwendigen Fähigkeiten verfügen und auf unserer Seite stehen.\n\nSagt Cyrille, die Eule schreit in der Dämmerung.\n\nInformiert Lorin, dass der Säbler auf dem Platz herumstreunt.\n\nErwähnt Sylessa gegenüber, dass der grausame Fassmeister seinen letzten Atemzug getan hat.\n\nSie werden wissen, was zu tun ist.\n\nSprecht mit Vanthir, wenn diese Sache erledigt ist.", sourceObjective = "Rekrutiert Sylessa, Cyrille und Lorin und zieht dann los, um Aufseher Durant zu töten.", completion = "Von jetzt an werden sie die Dämmerlilie ernst nehmen müssen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42795] = { id = 42795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Sanaar" }
quests[42796] = { id = 42796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Brutmutter Shu'malis" }
quests[42797] = { id = 42797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Sichelmeister Cil'raman" }
