quests[42799] = { id = 42799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Oglok der Rasende" }
quests[42800] = { id = 42800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Valeera Sanguinar", sourceObjective = "Selbstverständlich werde ich als Euer Champion dienen. Mitgefangen, mitgehangen, wie es so schön heißt.\n\nWir werden gut zusammenarbeiten. Ich hole das Beste aus Euch heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[42801] = { id = 42801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzvorarbeit", description = "Bevor Ihr Euch in den Schwarzen Tempel begebt, brauchen wir weitere Informationen. Wir wollen schließlich nicht, dass Ihr in eine Falle teleportiert werdet.\n\nWir müssen die Struktur ihrer Streitkräfte, die Patrouillenzeiten und neue Verteidigungsmechanismen in Erfahrung bringen... und was Akama zum Frühstück verzehrt.\n\n<Belath grinst.>\n\nIch schlage vor, Ihr schickt Eure zerschlagenen Krieger aus, damit sie sich darum kümmern. Sie können sich im Tempel unter den Rest von Akamas Streitkräften der Aschenzungen mischen. Wer es wieder herausschafft, kann uns sagen, was wir wissen müssen.\n\nEin beaufsichtigender Champion oder zwei können sich draußen vorm Tempel umsehen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Schwarzvorarbeit\" ab.", completion = "Belath ist so ein Schatz. Wie umsichtig von ihm, Späher zu organisieren.\n\nIch hoffe, dass nicht allzu viele Zerschlagene gestorben sind, um an diese Informationen zu gelangen.\n\nJedenfalls habe ich jetzt die Mittel und den perfekten Ort im Schwarzen Tempel für unseren großen Auftritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42802] = { id = 42802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sicherung Mardums", description = "Unten auf Mardum gibt es erhöhte dämonische Aktivität. Es gibt dort immer noch Dämonen, die nach unserer ersten Invasion übrig geblieben sind.\n\nUm jegliche Bedrohung für die Teufelshammer auszuschalten, müssen sie endlich vernichtet werden.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Die Sicherung Mardums\" ab.", completion = "Ariana Feuerherz?! Ich dachte, die wäre bei unserem ersten Besuch hier gestorben. Wie schrecklich, dass sie die ganze Zeit dort unten gewesen ist. Aber was für eine erstaunliche Überlebenskünstlerin!\n\nIch erinnere mich, dass sie eine ausgezeichnete Ausbilderin für {class} gewesen ist. Wir sollten uns ihre Fähigkeiten umgehend zunutze machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42803] = { id = 42803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Dun Morogh" }
quests[42804] = { id = 42804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Azshara" }
quests[42805] = { id = 42805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Hillsbrad Foothills" }
