quests[42807] = { id = 42807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Commander" }
quests[42808] = { id = 42808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Adepten", description = "Ich würde unseren Sieg zwar gerne durch Finesse erreichen, aber die kalte, harte Realität zeigt, dass wir schlagkräftigere Truppen brauchen.\n\nWir strapazieren Gaardouns Fähigkeiten, neue Zerschlagene zu rekrutieren, ohnehin schon über Gebühr.\n\nDoch jetzt, da wir Ariana Feuerherz haben, kann sie neue Dämonenjäger für uns ausbilden.", sourceObjective = "Sprecht mit Eurer Illidarirekrutiererin Ariana Feuerherz.", completion = "Ich bin froh, dass Ariana sich erholt hat und bereit ist, unsere ersten neuen {class} auszubilden.\n\nEs ist schon eine Weile her, dass wir frisches Blut in unseren Reihen hatten.", sourceObjectiveStatus = "unverified-source-field" }
